-- Hash simples (usado para saber se o texto da update mudou)
local function SimpleHash(str)
    local h = 5381
    for i = 1, #str do
        h = (h * 33 + str:byte(i)) % 4294967296
    end
    return string.format("%08x", h)
end

-- Cria um tema completo (cores + bordas + transparencias) de forma curta
local function MakeTheme(edge, mid, hub2, stroke, accent, text, dark, strokeHex, image, imageTransparency)
    return {
        ["Color Hub 1"] = ColorSequence.new({
            ColorSequenceKeypoint.new(0.00, edge),
            ColorSequenceKeypoint.new(0.50, mid),
            ColorSequenceKeypoint.new(1.00, edge)
        }),
        ["Color Hub 2"] = hub2,
        ["Color Stroke"] = stroke,
        ["Color Theme"] = accent,
        ["Color Text"] = text,
        ["Color Dark Text"] = dark,
        ["HubImage"] = image and ("embedded:" .. image) or "",
        -- bordas e transparencias fazem parte do tema
        StrokeColor = strokeHex,
        MinimizeStrokeColor = strokeHex,
        StrokeTransparency = 0,
        GlobalTransparency = 0,
        HubTransparency = 0,
        HubImageTransparency = imageTransparency or 0,
    }
end

