local function HexToColor(hex, fallback)
    local ok, color = pcall(Color3.fromHex, hex)
    if ok and color then return color end
    return fallback or Color3.fromRGB(138, 43, 226)
end

local function UpdateStroke(stroke)
    if not stroke then return end
    stroke.Color = HexToColor(MyLibrary.Save.StrokeColor or "#8A2BE2")
    stroke.Transparency = MyLibrary.Save.StrokeTransparency or 0
end

local function ApplyBorder(guiObject)
    if not guiObject or not guiObject:IsA("GuiObject") then return end

    local stroke = guiObject:FindFirstChild("LibBorder")
    if not stroke then
        stroke = Instance.new("UIStroke")
        stroke.Name = "LibBorder"
        stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Parent = guiObject
        table.insert(MyLibrary.StrokeInstances, stroke)
    end

    UpdateStroke(stroke)
end

