local Flags = MyLibrary.Flags

----------------------------------------------------------------------
-- CRIACAO DE INSTANCIAS
----------------------------------------------------------------------
local SetProps, SetChildren, InsertTheme, Create do
    InsertTheme = function(Inst, Type)
        table.insert(MyLibrary.Instances, {
            Instance = Inst,
            Type = Type
        })
        return Inst
    end

    SetChildren = function(Inst, Children)
        if Children then
            for _, Child in pairs(Children) do
                Child.Parent = Inst
            end
        end
        return Inst
    end

    SetProps = function(Inst, Props)
        if Props then
            for prop, value in pairs(Props) do
                Inst[prop] = value
            end
        end
        return Inst
    end

    Create = function(...)
        local args = {...}
        local new = Instance.new(args[1])

        if type(args[2]) == "table" then
            SetProps(new, args[2])
            SetChildren(new, args[3])
        elseif typeof(args[2]) == "Instance" then
            new.Parent = args[2]
            SetProps(new, args[3])
            SetChildren(new, args[4])
        end
        return new
    end
end

local function Color3ToHex(c)
    return string.format("#%02X%02X%02X", math.round(c.R * 255), math.round(c.G * 255), math.round(c.B * 255))
end

local function HexToColor3(hex)
    hex = tostring(hex):gsub("#", "")
    local r = tonumber(hex:sub(1, 2), 16) or 0
    local g = tonumber(hex:sub(3, 4), 16) or 0
    local b = tonumber(hex:sub(5, 6), 16) or 0
    return Color3.fromRGB(r, g, b)
end

local function SerializeThemeValue(v)
    if typeof(v) == "Color3" then
        return { T = "Color3", C = Color3ToHex(v) }
    elseif typeof(v) == "ColorSequence" then
        local kps = {}
        for _, kp in ipairs(v.Keypoints) do
            table.insert(kps, { Time = kp.Time, C = Color3ToHex(kp.Value) })
        end
        return { T = "ColorSequence", K = kps }
    end
end

local function DeserializeThemeValue(data)
    if type(data) ~= "table" then return nil end
    if data.T == "Color3" and data.C then
        return HexToColor3(data.C)
    elseif data.T == "ColorSequence" and type(data.K) == "table" then
        local kps = {}
        for _, kp in ipairs(data.K) do
            table.insert(kps, ColorSequenceKeypoint.new(kp.Time, HexToColor3(kp.C)))
        end
        if #kps >= 2 then
            return ColorSequence.new(kps)
        end
    end
end

-- Copia dos temas originais (antes de aplicar cores customizadas)
local OriginalThemes = {}
for themeName, themeTable in pairs(MyLibrary.Themes) do
    OriginalThemes[themeName] = {}
    for key, value in pairs(themeTable) do
        OriginalThemes[themeName][key] = value
    end
end

----------------------------------------------------------------------
-- FUNCS
----------------------------------------------------------------------
local Funcs = {} do
    function Funcs:InsertCallback(tab, func)
        if type(func) == "function" then
            table.insert(tab, func)
        end
        return func
    end

    function Funcs:FireCallback(tab, ...)
        for _, v in ipairs(tab) do
            if type(v) == "function" then
                task.spawn(v, ...)
            end
        end
    end

    -- Bool == nil alterna; true/false define
    function Funcs:ToggleVisible(Obj, Bool)
        if Bool == nil then
            Obj.Visible = not Obj.Visible
        else
            Obj.Visible = Bool
        end
    end

    function Funcs:GetConnectionFunctions(ConnectedFuncs, func)
        local Connected = { Function = func, Connected = true }

        function Connected:Disconnect()
            if self.Connected then
                local index = table.find(ConnectedFuncs, self.Function)
                if index then table.remove(ConnectedFuncs, index) end
                self.Connected = false
            end
        end

        function Connected:Fire(...)
            if self.Connected then
                task.spawn(self.Function, ...)
            end
        end

        return Connected
    end

    function Funcs:GetCallback(Configs, index)
        local func = Configs[index] or Configs.Callback or function() end
        if type(func) == "table" then
            return { function(Value) func[1][func[2]] = Value end }
        end
        return { func }
    end
end

----------------------------------------------------------------------
-- CONNECTIONS (eventos da lib)
----------------------------------------------------------------------
local Connections, Connection = {}, MyLibrary.Connection do
    local function NewConnectionList(List)
        for _, CoName in ipairs(List) do
            local ConnectedFuncs, Connect = {}, {}
            Connection[CoName] = Connect
            Connections[CoName] = ConnectedFuncs
            Connect.Name = CoName

            function Connect:Connect(func)
                if type(func) == "function" then
                    table.insert(ConnectedFuncs, func)
                    return Funcs:GetConnectionFunctions(ConnectedFuncs, func)
                end
            end

            function Connect:Once(func)
                if type(func) == "function" then
                    local Connected
                    local OnceFunc = function(...)
                        Connected:Disconnect()
                        task.spawn(func, ...)
                    end
                    table.insert(ConnectedFuncs, OnceFunc)
                    Connected = Funcs:GetConnectionFunctions(ConnectedFuncs, OnceFunc)
                    return Connected
                end
            end
        end
    end

    function Connection:FireConnection(CoName, ...)
        local Name = type(CoName) == "string" and CoName or CoName.Name
        local List = Connections[Name]
        if not List then return end
        for _, Func in ipairs(table.clone(List)) do
            task.spawn(Func, ...)
        end
    end

    NewConnectionList({"FlagsChanged", "ThemeChanged", "ThemeApplied", "FileSaved", "ThemeChanging", "OptionAdded"})
end

local GetFlag, SetFlag, CheckFlag do
    CheckFlag = function(Name)
        return type(Name) == "string" and Flags[Name] ~= nil
    end

    GetFlag = function(Name)
        return type(Name) == "string" and Flags[Name]
    end

    SetFlag = function(Flag, Value)
        if Flag and (Value ~= Flags[Flag] or type(Value) == "table") then
            Flags[Flag] = Value
            Connection:FireConnection("FlagsChanged", Flag, Value)
        end
    end

    local Queued = false
    Connection.FlagsChanged:Connect(function()
        if Queued or type(Settings.ScriptFile) ~= "string" or not writefile then return end
        Queued = true
        task.delay(0.2, function()
            Queued = false
            local path = GetFullPath(Settings.ScriptFile)
            local ok, encoded = pcall(function() return HttpService:JSONEncode(Flags) end)
            if ok and pcall(writefile, path, encoded) then
                Connection:FireConnection("FileSaved", "Script-Flags", path, encoded)
            end
        end)
    end)
end

