----------------------------------------------------------------------
-- TWEEN / DRAG / SLIDER
----------------------------------------------------------------------
local function IsPress(Input)
    return Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch
end

-- Se wait == true, a thread atual espera o fim do tween (com limite de seguranca)
local function CreateTween(Configs)
    local Inst = Configs[1] or Configs.Instance
    local Prop = Configs[2] or Configs.Prop
    local NewVal = Configs[3] or Configs.NewVal
    local Time = Configs[4] or Configs.Time or 0.5
    local TweenWait = Configs[5] or Configs.wait or false

    local ok, Tween = pcall(function()
        return TweenService:Create(Inst, TweenInfo.new(Time, Enum.EasingStyle.Quint), {[Prop] = NewVal})
    end)
    if not ok or not Tween then return end

    Tween:Play()
    if TweenWait then
        local done = false
        local c = Tween.Completed:Connect(function() done = true end)
        local waited = 0
        while not done and waited < Time + 0.3 do
            waited = waited + task.wait()
        end
        c:Disconnect()
    end
    return Tween
end

-- Salva so quando o usuario SOLTA o dragger (funciona em mouse e touch)
local function ConnectSave(Inst, func)
    local pressed = false
    Inst.InputBegan:Connect(function(Input)
        if IsPress(Input) then pressed = true end
    end)
    Track(UserInputService.InputEnded:Connect(function(Input)
        if pressed and IsPress(Input) then
            pressed = false
            task.delay(0.15, func)
        end
    end))
end

-- Drag em mouse E touch.
-- Handle = objeto que recebe o clique/toque; Target = objeto que se move.
-- (Se Target for omitido, o proprio Handle e movido.)
local function MakeDrag(Handle, Target)
    Target = Target or Handle
    Handle.Active = true
    pcall(function() Handle.AutoButtonColor = false end)

    local DragStart, StartPos, ActiveInput

    Handle.InputBegan:Connect(function(Input)
        if IsPress(Input) then
            ActiveInput = Input
            DragStart = Input.Position
            StartPos = Target.Position
            Target:SetAttribute("Dragged", false)
        end
    end)

    Track(UserInputService.InputChanged:Connect(function(Input)
        if not ActiveInput then return end
        if Input.UserInputType == Enum.UserInputType.MouseMovement
            or (Input.UserInputType == Enum.UserInputType.Touch and Input == ActiveInput) then
            local delta = Input.Position - DragStart
            if delta.Magnitude > 6 then
                Target:SetAttribute("Dragged", true)
            end
            local newPos = UDim2.new(
                StartPos.X.Scale, StartPos.X.Offset + delta.X / UIScale,
                StartPos.Y.Scale, StartPos.Y.Offset + delta.Y / UIScale
            )
            CreateTween({Target, "Position", newPos, 0.08})
        end
    end))

    Track(UserInputService.InputEnded:Connect(function(Input)
        if Input == ActiveInput or Input.UserInputType == Enum.UserInputType.MouseButton1 then
            ActiveInput = nil
        end
    end))

    return Handle
end

-- Acha o ScrollingFrame que contem um objeto (usado para travar o scroll durante o arrasto)
local function GetScroller(Inst)
    if not Inst then return nil end
    if Inst:IsA("ScrollingFrame") then return Inst end
    return Inst:FindFirstAncestorOfClass("ScrollingFrame")
end

-- Arrasto de slider (mouse + touch)
local function BindSlider(Holder, Bar, Icon, ScrollParent, OnRelease)
    local dragging = false
    local ActiveInput

    local function SetFromX(x)
        local width = math.max(Bar.AbsoluteSize.X, 1)
        Icon.Position = UDim2.new(math.clamp((x - Bar.AbsolutePosition.X) / width, 0, 1), 0, 0.5, 0)
    end

    Holder.InputBegan:Connect(function(Input)
        if not IsPress(Input) then return end
        dragging = true
        ActiveInput = Input
        local scroller = GetScroller(ScrollParent)
        if scroller then scroller.ScrollingEnabled = false end
        CreateTween({Icon, "BackgroundTransparency", 0, 0.3})
        SetFromX(Input.Position.X)
    end)

    Track(UserInputService.InputChanged:Connect(function(Input)
        if not dragging then return end
        if Input.UserInputType == Enum.UserInputType.MouseMovement
            or (Input.UserInputType == Enum.UserInputType.Touch and Input == ActiveInput) then
            SetFromX(Input.Position.X)
        end
    end))

    Track(UserInputService.InputEnded:Connect(function(Input)
        if dragging and (Input == ActiveInput or Input.UserInputType == Enum.UserInputType.MouseButton1) then
            dragging = false
            ActiveInput = nil
            local scroller = GetScroller(ScrollParent)
            if scroller then scroller.ScrollingEnabled = true end
            CreateTween({Icon, "BackgroundTransparency", 0.2, 0.3})
            if OnRelease then OnRelease() end
        end
    end))
end

----------------------------------------------------------------------
-- SISTEMA DE IMAGENS
----------------------------------------------------------------------
local IMAGES_FOLDER = LibFolder .. "/imagens"
local JSON_FILE_PATH = IMAGES_FOLDER .. "/imagens.json"

SafeMakeFolder(IMAGES_FOLDER)

local requestFunc = request or http_request or (syn and syn.request)
local getAssetFunc = getcustomasset or getsynasset

local IMAGE_FILES = {
    Hub = IMAGES_FOLDER .. "/ImageHub.png",
    Topbar = IMAGES_FOLDER .. "/ImageTopbar.png",
    Minimize = IMAGES_FOLDER .. "/ImageMinimize.png",
}

local LastImageLinks = {
    Hub = nil,
    Topbar = nil,
    Minimize = nil,
}

-- Decodifica base64 (usa a funcao do executor se existir; senao decodifica em Lua)
local B64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64_LOOKUP = {}
for i = 1, 64 do B64_LOOKUP[B64_CHARS:sub(i, i)] = i - 1 end

local function DecodeBase64(data)
    local native = (crypt and (crypt.base64decode or (crypt.base64 and crypt.base64.decode)))
        or base64decode or base64_decode
        or (syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode)
    if native then
        local ok, res = pcall(native, data)
        if ok and type(res) == "string" and #res > 0 then return res end
    end

    data = data:gsub("[^%w%+/=]", "")
    local out = {}
    for i = 1, #data, 4 do
        local a = B64_LOOKUP[data:sub(i, i)]
        local b = B64_LOOKUP[data:sub(i + 1, i + 1)]
        local c = B64_LOOKUP[data:sub(i + 2, i + 2)]
        local d = B64_LOOKUP[data:sub(i + 3, i + 3)]
        if not (a and b) then break end
        local n = bit32.lshift(a, 18) + bit32.lshift(b, 12) + bit32.lshift(c or 0, 6) + (d or 0)
        out[#out + 1] = string.char(bit32.band(bit32.rshift(n, 16), 255))
        if c then out[#out + 1] = string.char(bit32.band(bit32.rshift(n, 8), 255)) end
        if d then out[#out + 1] = string.char(bit32.band(n, 255)) end
    end
    return table.concat(out)
end

-- kind = "Hub" | "Topbar" | "Minimize"
local function ProcessAndApplyImage(objectTarget, imageInput, kind)
    if not objectTarget then return "" end
    if type(kind) ~= "string" or not IMAGE_FILES[kind] then
        warn("[Images] kind invalido:", tostring(kind))
        return ""
    end

    local isImage = objectTarget:IsA("ImageLabel") or objectTarget:IsA("ImageButton")

    if type(imageInput) ~= "string" or imageInput == "" then
        if isImage then objectTarget.Image = "" end
        return ""
    end

    -- Caso 0: imagem embutida na lib ("embedded:Nome")
    local embeddedName = imageInput:match("^embedded:(.+)$")
    if embeddedName then
        local data = EMBEDDED_IMAGES[embeddedName]
        if not data then
            warn("[Images] Imagem embutida nao existe: " .. embeddedName)
            return ""
        end
        if not getAssetFunc or not writefile then
            warn("[Images] Executor nao suporta writefile/getcustomasset.")
            return imageInput
        end

        local fileName = IMAGES_FOLDER .. "/Embedded_" .. embeddedName .. ".png"
        if not (isfile and isfile(fileName)) then
            if not pcall(writefile, fileName, DecodeBase64(data)) then
                warn("[Images] Falha ao salvar imagem embutida: " .. fileName)
                return imageInput
            end
        end

        LastImageLinks[kind] = imageInput
        local assetPath = getAssetFunc(fileName)
        if isImage then objectTarget.Image = assetPath end
        return assetPath
    end

    -- Caso 1: link HTTP
    if imageInput:find("https://") or imageInput:find("http://") then
        if not requestFunc or not getAssetFunc or not writefile then
            warn("[Images] Executor nao suporta request/getcustomasset.")
            return imageInput
        end

        local fileName = IMAGE_FILES[kind]

        -- Mesmo link e arquivo ja existe: usa o cache
        if LastImageLinks[kind] == imageInput and isfile and isfile(fileName) then
            local assetPath = getAssetFunc(fileName)
            if isImage then objectTarget.Image = assetPath end
            return assetPath
        end

        if isfile and isfile(fileName) and delfile then
            pcall(delfile, fileName)
        end

        if isImage then objectTarget.Image = "" end

        local ok, response = pcall(requestFunc, {
            Url = imageInput,
            Method = "GET",
            Headers = {["User-Agent"] = "Mozilla/5.0"}
        })

        if ok and response and response.Body and #response.Body > 0 then
            if not pcall(writefile, fileName, response.Body) then
                warn("[Images] Falha ao salvar arquivo: " .. fileName)
                return imageInput
            end

            LastImageLinks[kind] = imageInput

            local assetPath = getAssetFunc(fileName)
            if isImage then
                objectTarget.Image = ""
                task.wait()
                objectTarget.Image = assetPath
            end
            return assetPath
        else
            warn("[Images] Falha ao baixar imagem: " .. tostring(imageInput))
            return imageInput
        end
    end

    -- Caso 2: rbxassetid:// ou ID puro
    local formattedId = imageInput
    if not imageInput:find("rbxassetid://") and not imageInput:find("rbxasset://") then
        formattedId = "rbxassetid://" .. imageInput
    end

    LastImageLinks[kind] = imageInput
    if isImage then objectTarget.Image = formattedId end
    return formattedId
end

local function GetDefaultThemeImages()
    local theme = MyLibrary.Themes[MyLibrary.Save.Theme] or {}
    return {
        HubImage = theme["HubImage"] or "",
        MinimizeImage = theme["MinimizeImage"] or "",
        TopbarImage = theme["TopbarImage"] or "",
    }
end

local function LoadImageSettings()
    local defaults = GetDefaultThemeImages()

    if isfile and readfile and isfile(JSON_FILE_PATH) then
        local ok, decoded = pcall(function()
            return HttpService:JSONDecode(readfile(JSON_FILE_PATH))
        end)
        if ok and type(decoded) == "table" then
            defaults.HubImage = decoded.HubImage or defaults.HubImage
            defaults.MinimizeImage = decoded.MinimizeImage or defaults.MinimizeImage
            defaults.TopbarImage = decoded.TopbarImage or defaults.TopbarImage
        end
    else
        SaveJson(JSON_FILE_PATH, defaults)
    end
    return defaults
end

local function SaveImageSettings(data)
    SaveJson(JSON_FILE_PATH, data)
end

local CurrentImageSettings = LoadImageSettings()

-- Se o arquivo em cache existe e o link salvo e o mesmo, nao baixa de novo
LastImageLinks.Hub = CurrentImageSettings.HubImage
LastImageLinks.Minimize = CurrentImageSettings.MinimizeImage
LastImageLinks.Topbar = CurrentImageSettings.TopbarImage

local function ApplyCustomColorsToTheme(targetTheme)
    for key, data in pairs(MyLibrary.Save.CustomColors or {}) do
        local val = DeserializeThemeValue(data)
        if val and targetTheme[key] ~= nil then
            targetTheme[key] = val
        end
    end
end

local Theme = MyLibrary.Themes[MyLibrary.Save.Theme]
ApplyCustomColorsToTheme(Theme)

----------------------------------------------------------------------
-- ELEMENTOS BASE
----------------------------------------------------------------------
local function AddEle(Name, Func)
    MyLibrary.Elements[Name] = Func
end

local function Make(Ele, Inst, props, ...)
    return MyLibrary.Elements[Ele](Inst, props, ...)
end

AddEle("Corner", function(parent, CornerRadius)
    return Create("UICorner", parent, {
        CornerRadius = CornerRadius or UDim.new(0, 7)
    })
end)

AddEle("Stroke", function(parent, props, ...)
    local args = {...}
    return InsertTheme(SetProps(Create("UIStroke", parent, {
        Color = args[1] or Theme["Color Stroke"],
        Thickness = args[2] or 1,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    }), props), "Stroke")
end)

AddEle("Button", function(parent, props, ...)
    local args = {...}
    local New = InsertTheme(SetProps(Create("TextButton", parent, {
        Text = "",
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Theme["Color Hub 2"],
        AutoButtonColor = false
    }), props), "Frame")

    AddTransparency(New)
    ApplyBorder(New)

    New.MouseEnter:Connect(function()
        local base = MyLibrary.Save.GlobalTransparency or 0
        New.BackgroundTransparency = math.max(0.4, base)
    end)
    New.MouseLeave:Connect(function()
        New.BackgroundTransparency = MyLibrary.Save.GlobalTransparency or 0
    end)
    if args[1] then
        New.Activated:Connect(args[1])
    end
    return New
end)

AddEle("Gradient", function(parent, props, ...)
    return InsertTheme(SetProps(Create("UIGradient", parent, {
        Color = Theme["Color Hub 1"]
    }), props), "Gradient")
end)

local function ButtonFrame(Parent, Title, Description, HolderSize)
    local TitleL = InsertTheme(Create("TextLabel", {
        Font = MyLibrary.CurrentFont,
        TextColor3 = Theme["Color Text"],
        Size = UDim2.new(1, -20),
        AutomaticSize = "Y",
        Position = UDim2.new(0, 0, 0.5),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        TextTruncate = "AtEnd",
        TextSize = 10,
        TextXAlignment = "Left",
        Text = "",
        RichText = true
    }), "Text")

    local DescL = InsertTheme(Create("TextLabel", {
        Font = MyLibrary.CurrentFont,
        TextColor3 = Theme["Color Dark Text"],
        Size = UDim2.new(1, -20),
        AutomaticSize = "Y",
        Position = UDim2.new(0, 12, 0, 15),
        BackgroundTransparency = 1,
        TextWrapped = true,
        TextSize = 8,
        TextXAlignment = "Left",
        Text = "",
        RichText = true
    }), "DarkText")

    local Frame = Make("Button", Parent, {
        Size = UDim2.new(1, 0, 0, 25),
        AutomaticSize = "Y",
        Name = "Option"
    })
    Make("Corner", Frame, UDim.new(0, 6))

    local LabelHolder = Create("Frame", Frame, {
        AutomaticSize = "Y",
        BackgroundTransparency = 1,
        Size = HolderSize,
        Position = UDim2.new(0, 10, 0),
        AnchorPoint = Vector2.new(0, 0)
    }, {
        Create("UIListLayout", {
            SortOrder = "LayoutOrder",
            VerticalAlignment = "Center",
            Padding = UDim.new(0, 2)
        }),
        Create("UIPadding", {
            PaddingBottom = UDim.new(0, 5),
            PaddingTop = UDim.new(0, 5)
        }),
        TitleL,
        DescL,
    })

    local Label = {}
    function Label:SetTitle(NewTitle)
        if type(NewTitle) == "string" and NewTitle:gsub(" ", ""):len() > 0 then
            TitleL.Text = NewTitle
        end
    end
    function Label:SetDesc(NewDesc)
        if type(NewDesc) == "string" and NewDesc:gsub(" ", ""):len() > 0 then
            DescL.Visible = true
            DescL.Text = NewDesc
            LabelHolder.Position = UDim2.new(0, 10, 0)
            LabelHolder.AnchorPoint = Vector2.new(0, 0)
        else
            DescL.Visible = false
            DescL.Text = ""
            LabelHolder.Position = UDim2.new(0, 10, 0.5)
            LabelHolder.AnchorPoint = Vector2.new(0, 0.5)
        end
    end

    Label:SetTitle(Title)
    Label:SetDesc(Description)
    return Frame, Label
end

local function GetThemeImage(key)
    local theme = MyLibrary.Themes[MyLibrary.Save.Theme]
    if not theme then return nil end
    return theme[key]
end

local function GetColor(Inst)
    if Inst:IsA("Frame") then
        return "BackgroundColor3"
    elseif Inst:IsA("ImageLabel") or Inst:IsA("ImageButton") then
        return "ImageColor3"
    elseif Inst:IsA("TextLabel") or Inst:IsA("TextBox") or Inst:IsA("TextButton") then
        return "TextColor3"
    elseif Inst:IsA("ScrollingFrame") then
        return "ScrollBarImageColor3"
    elseif Inst:IsA("UIStroke") then
        return "Color"
    end
    return ""
end

----------------------------------------------------------------------
-- TEMAS
----------------------------------------------------------------------
local function ApplyThemeEntry(Val)
    local inst, kind = Val.Instance, Val.Type
    if not inst then return end

    if kind == "Gradient" then
        inst.Color = Theme["Color Hub 1"]
    elseif kind == "Frame" then
        inst.BackgroundColor3 = Theme["Color Hub 2"]
    else
        local prop = GetColor(inst)
        if prop == "" then return end
        if kind == "Stroke" then
            inst[prop] = Theme["Color Stroke"]
        elseif kind == "Theme" or kind == "ScrollBar" then
            inst[prop] = Theme["Color Theme"]
        elseif kind == "Text" then
            inst[prop] = Theme["Color Text"]
        elseif kind == "DarkText" or kind == "SubText" then
            inst[prop] = Theme["Color Dark Text"]
        end
    end
end

local function ApplyThemeToAll()
    for _, Val in ipairs(MyLibrary.Instances) do
        pcall(ApplyThemeEntry, Val)
    end
end

function MyLibrary:GetIcon(index)
    if type(index) ~= "string" or index:find("rbxassetid://") or #index == 0 then
        return index
    end

    local firstMatch = nil
    index = string.lower(index):gsub("lucide", ""):gsub("%-", "")

    for Name, Icon in pairs(self.Icons) do
        Name = Name:gsub("lucide", ""):gsub("%-", "")
        if Name == index then
            return Icon
        elseif not firstMatch and Name:find(index, 1, true) then
            firstMatch = Icon
        end
    end

    return firstMatch or index
end

function MyLibrary:SetThemeColor(key, value)
    local currentTheme = MyLibrary.Themes[MyLibrary.Save.Theme]
    if not currentTheme or currentTheme[key] == nil then
        warn("Chave de cor invalida:", tostring(key))
        return
    end

    if key == "Color Hub 1" and type(value) == "table" then
        if #value >= 3 then
            value = ColorSequence.new({
                ColorSequenceKeypoint.new(0.00, value[1]),
                ColorSequenceKeypoint.new(0.50, value[2]),
                ColorSequenceKeypoint.new(1.00, value[3])
            })
        else
            warn("Para 'Color Hub 1' passe uma tabela com 3 Color3.")
            return
        end
    end

    if value == nil then
        MyLibrary.Save.CustomColors[key] = nil
        currentTheme[key] = OriginalThemes[MyLibrary.Save.Theme][key]
    else
        MyLibrary.Save.CustomColors[key] = SerializeThemeValue(value)
        currentTheme[key] = value
    end

    SaveLib()
    Connection:FireConnection("ThemeChanged", MyLibrary.Save.Theme)
    ApplyThemeToAll()
end

-- Aplica bordas e transparencias guardadas dentro do tema (se ele tiver)
local function ApplyThemeExtras(t)
    if t.StrokeColor ~= nil then MyLibrary:SetStrokeColor(t.StrokeColor) end
    if t.MinimizeStrokeColor ~= nil then MyLibrary:SetMinimizeStrokeColor(t.MinimizeStrokeColor) end
    if t.StrokeTransparency ~= nil then MyLibrary:SetStrokeTransparency(t.StrokeTransparency) end
    if t.GlobalTransparency ~= nil then MyLibrary:SetGlobalTransparency(t.GlobalTransparency) end
    if t.HubTransparency ~= nil then MyLibrary:SetHubTransparency(t.HubTransparency) end
    if t.HubImageTransparency ~= nil then MyLibrary:SetHubImageTransparency(t.HubImageTransparency) end
end

-- Registra um tema novo na library. Cores que faltarem vem do tema "Customize".
function MyLibrary:AddTheme(name, data)
    if type(name) ~= "string" or name == "" or type(data) ~= "table" then return false end

    local base = OriginalThemes["Customize"] or {}
    local t = {}
    for _, key in ipairs({"Color Hub 1", "Color Hub 2", "Color Stroke", "Color Theme", "Color Text", "Color Dark Text"}) do
        if data[key] ~= nil then t[key] = data[key] else t[key] = base[key] end
    end
    for k, v in pairs(data) do
        if t[k] == nil then t[k] = v end
    end

    MyLibrary.Themes[name] = t
    OriginalThemes[name] = {}
    for k, v in pairs(t) do OriginalThemes[name][k] = v end
    return true
end

-- Lista os temas da library (Customize primeiro, o resto em ordem alfabetica)
function MyLibrary:GetThemeNames()
    local names = {}
    for name in pairs(MyLibrary.Themes) do
        if name ~= "Customize" then table.insert(names, name) end
    end
    table.sort(names)
    if MyLibrary.Themes["Customize"] then table.insert(names, 1, "Customize") end
    return names
end

-- Aplica um tema da library do jeito que ele foi desenhado
-- (cores, bordas, transparencias e imagens). KeepCustom = true mantem as cores editadas.
function MyLibrary:SetTheme(NewTheme, KeepCustom)
    if not VerifyTheme(NewTheme) then return end

    local cur = MyLibrary.Themes[NewTheme]
    if not OriginalThemes[NewTheme] then
        OriginalThemes[NewTheme] = {}
        for k, v in pairs(cur) do OriginalThemes[NewTheme][k] = v end
    end
    for k, v in pairs(OriginalThemes[NewTheme]) do cur[k] = v end

    if not KeepCustom then MyLibrary.Save.CustomColors = {} end

    MyLibrary.Save.Theme = NewTheme
    SaveLib()
    Theme = cur
    ApplyCustomColorsToTheme(Theme)

    if not KeepCustom then ApplyThemeExtras(cur) end

    Connection:FireConnection("ThemeChanged", NewTheme)
    ApplyThemeToAll()
    Connection:FireConnection("ThemeApplied", NewTheme)

    -- Imagens do tema (chave ausente = nao mexe; "" = remove a imagem)
    task.spawn(function()
        local function apply(key, kind, getter)
            local img = GetThemeImage(key)
            if img == nil then return end
            CurrentImageSettings[key] = img
            local target = getter()
            if target then
                LastImageLinks[kind] = nil
                ProcessAndApplyImage(target, img, kind)
            end
        end

        apply("HubImage", "Hub", function() return MyLibrary.HubImageLabel end)
        apply("MinimizeImage", "Minimize", function() return MyLibrary.MinimizeExternalButton end)
        apply("TopbarImage", "Topbar", function() return MyLibrary.TopbarImageLabel end)

        SaveImageSettings(CurrentImageSettings)
    end)
end

function MyLibrary:SetScale(NewScale)
    local vp = workspace.CurrentCamera.ViewportSize
    NewScale = vp.Y / math.clamp(NewScale, 300, 2000)
    UIScale, ScreenGui.Scale.Scale = NewScale, NewScale
end

function MyLibrary:SetGlobalTransparency(value)
    value = tonumber(value)
    if not value then return end
    value = math.clamp(value, 0, 1)

    MyLibrary.Save.GlobalTransparency = value
    SaveLib()

    for _, instance in ipairs(MyLibrary.TransparencyInstances) do
        if instance and instance.Parent then
            if instance:IsA("Frame") or instance:IsA("TextButton") or instance:IsA("ImageButton") or instance:IsA("ScrollingFrame") then
                instance.BackgroundTransparency = value
            end
        end
    end
end

