    if not target then return end

    local themeImg = GetThemeImage(settingKey)
    if not themeImg or themeImg == "" then
        warn("Tema atual nao possui " .. settingKey .. " definida.")
        return
    end

    LastImageLinks[kind] = nil
    ProcessAndApplyImage(target, themeImg, kind)
    CurrentImageSettings[settingKey] = themeImg
    SaveImageSettings(CurrentImageSettings)
end

