function MyLibrary:SetFont(fontInput)
    if type(fontInput) == "string" then
        local ok, f = pcall(function() return Enum.Font[fontInput] end)
        fontInput = ok and f or nil
    end

    if typeof(fontInput) ~= "EnumItem" or fontInput.EnumType ~= Enum.Font then
        warn("Fonte invalida. Use uma string ou Enum.Font.")
        return
    end

    MyLibrary.Save.Font = fontInput.Name
    MyLibrary.CurrentFont = fontInput
    SaveLib()

    for _, val in ipairs(MyLibrary.Instances) do
        local inst = val.Instance
        if inst and (inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox")) then
            inst.Font = fontInput
        end
    end
end

----------------------------------------------------------------------
-- TRADUCAO (embutida na lib)
-- Procura textos dentro do ScreenGui da lib e troca SO os que forem
-- iguais a uma entrada da tabela. O resto nao e tocado.
----------------------------------------------------------------------
local Translation = {
    Link = DEFAULT_TRANSLATION_LINK,
    Frases = nil,      -- { pt = {...}, en = {...}, es = {...}, it = {...} }
    Language = "en",
}

local TranslationRecords = setmetatable({}, {__mode = "k"}) -- obj -> {Original, Shown}
local TranslationHooked = setmetatable({}, {__mode = "k"})

local function DetectLanguage()
    local saved = MyLibrary.Save.Language
    if type(saved) == "string" and saved ~= "" then return saved end

    local ok, locale = pcall(function() return Player.LocaleId end)
    local code = (ok and type(locale) == "string" and locale:sub(1, 2):lower()) or "en"
    if code == "pt" or code == "en" or code == "es" or code == "it" then
        return code
    end
    return "en"
end

Translation.Language = DetectLanguage()

local function GetDictionary()
    if type(Translation.Frases) ~= "table" then return nil end
    local dic = Translation.Frases[Translation.Language]
    if type(dic) == "table" and next(dic) ~= nil then return dic end
    return nil
end

local function IsTextObject(obj)
    return obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")
end

local function TranslateObject(obj)
    if not obj.Parent then return end
    local prop = obj:IsA("TextBox") and "PlaceholderText" or "Text"
    local current = obj[prop]
    if current == "" then return end

    local dic = GetDictionary()
    local rec = TranslationRecords[obj]

    -- se o texto atual nao e o que a lib colocou, o script mudou o texto: vira o novo original
    local original = (rec and rec.Shown == current) and rec.Original or current
    local new = dic and dic[original]

    if type(new) == "string" and new ~= "" then
        TranslationRecords[obj] = {Original = original, Shown = new}
        if new ~= current then obj[prop] = new end
    elseif rec and rec.Shown == current then
        -- esse idioma nao tem traducao: volta ao texto original
        TranslationRecords[obj] = nil
        if rec.Original ~= current then obj[prop] = rec.Original end
    end
end

local function HookTextObject(obj)
    if TranslationHooked[obj] or not IsTextObject(obj) then return end
    TranslationHooked[obj] = true

    local prop = obj:IsA("TextBox") and "PlaceholderText" or "Text"
    obj:GetPropertyChangedSignal(prop):Connect(function()
        local rec = TranslationRecords[obj]
        if rec and rec.Shown == obj[prop] then return end -- foi a propria traducao
        if not rec and not GetDictionary() then return end
        TranslateObject(obj)
    end)
end

local function TranslateAll()
    for _, d in ipairs(ScreenGui:GetDescendants()) do
        if IsTextObject(d) then
            HookTextObject(d)
            TranslateObject(d)
        end
    end
end

-- textos criados depois (dropdowns, notificacoes etc.)
ScreenGui.DescendantAdded:Connect(function(obj)
    if IsTextObject(obj) then
        HookTextObject(obj)
        task.defer(TranslateObject, obj)
    end
end)

-- source = link (string) ou tabela pronta
local function LoadTranslations(source)
    local data
    if type(source) == "table" then
        data = source
    elseif type(source) == "string" and source ~= "" then
        local ok, res = pcall(function()
            return loadstring(game:HttpGet(source))()
        end)
        if ok and type(res) == "table" then
            data = res
        else
            warn("[Traducao] Nao foi possivel carregar a tabela: " .. tostring(source))
        end
    end

    if type(data) ~= "table" then return false end
    if type(data.Frases) == "table" then data = data.Frases end

    Translation.Frases = data
    TranslateAll()
    return true
end

function MyLibrary:GetLanguage()
    return Translation.Language
end

function MyLibrary:SetLanguage(code)
    if type(code) ~= "string" or code == "" then return end
    code = code:lower()
    Translation.Language = code
    MyLibrary.Save.Language = code
    SaveLib()
    TranslateAll()
end

function MyLibrary:Translate(text)
    local dic = GetDictionary()
    return (dic and dic[text]) or text
end

function MyLibrary:SetTranslationLink(source)
    Translation.Link = source
    return LoadTranslations(source)
end

----------------------------------------------------------------------
-- NOTIFICACOES (canto direito, entram pela lateral)
----------------------------------------------------------------------
local ActiveNotifications = {}
local NotifyOrder = 0
local MAX_NOTIFICATIONS = 4
local NOTIFY_WIDTH, NOTIFY_HEIGHT = 250, 66
local NOTIFY_HIDDEN_X = NOTIFY_WIDTH + 30

local function GetNotifyHolder()
    local holder = ScreenGui:FindFirstChild("Notifications")
    if not holder then
        holder = Create("Frame", ScreenGui, {
            Name = "Notifications",
            Size = UDim2.new(0, NOTIFY_WIDTH, 1, -20),
            Position = UDim2.new(1, -10, 0, 10),
            AnchorPoint = Vector2.new(1, 0),
            BackgroundTransparency = 1,
            ZIndex = 999
        }, {
            Create("UIListLayout", {
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 6),
                HorizontalAlignment = Enum.HorizontalAlignment.Right,
                VerticalAlignment = Enum.VerticalAlignment.Top
            })
        })
    end
    return holder
end

local function EvictOldestNotification()
    local oldest = table.remove(ActiveNotifications, 1)
    if oldest and oldest.Close then
        task.spawn(oldest.Close)
    end
end

-- Opts = { Title, SubTitle, Message, Image, Duration }
local function BuildNotification(Opts)
    local Holder = GetNotifyHolder()
    while #ActiveNotifications >= MAX_NOTIFICATIONS do
        EvictOldestNotification()
    end

    local Duration = tonumber(Opts.Duration) or 4
    local hasImage = type(Opts.Image) == "string" and Opts.Image ~= ""
    local hasSub = type(Opts.SubTitle) == "string" and Opts.SubTitle ~= ""
    local textX = hasImage and 60 or 12

    NotifyOrder = NotifyOrder + 1

    local Slot = Create("Frame", Holder, {
        Size = UDim2.new(0, NOTIFY_WIDTH, 0, NOTIFY_HEIGHT),
        BackgroundTransparency = 1,
        LayoutOrder = NotifyOrder,
        Name = "NotificationSlot"
    })

    local Card = InsertTheme(Create("Frame", Slot, {
        Size = UDim2.fromScale(1, 1),
        Position = UDim2.new(0, NOTIFY_HIDDEN_X, 0, 0),
        BackgroundColor3 = Theme["Color Hub 2"],
        BorderSizePixel = 0,
        ClipsDescendants = true,
        ZIndex = 1000,
        Name = "Notification"
    }), "Frame")
    Make("Corner", Card, UDim.new(0, 5))
    ApplyBorder(Card)

    -- faixa de destaque na esquerda
    InsertTheme(Create("Frame", Card, {
        Size = UDim2.new(0, 3, 1, 0),
        BackgroundColor3 = Theme["Color Theme"],
        BorderSizePixel = 0,
        ZIndex = 1001
    }), "Theme")

    if hasImage then
        local Img = Create("ImageLabel", Card, {
            Size = UDim2.new(0, 40, 0, 40),
