            ZIndex = 1001
        })
        Make("Corner", Img, UDim.new(0, 5))
    end

    local textWidth = UDim2.new(1, -(textX + 30), 0, 16)

    InsertTheme(Create("TextLabel", Card, {
        Size = textWidth,
