        TextSize = 13,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        ZIndex = 1001
    }), "Text")

    local messageY = 23
    if hasSub then
        InsertTheme(Create("TextLabel", Card, {
            Size = UDim2.new(1, -(textX + 30), 0, 12),
            Position = UDim2.new(0, textX, 0, 21),
            BackgroundTransparency = 1,
            Text = Opts.SubTitle,
            TextColor3 = Theme["Color Dark Text"],
            Font = MyLibrary.CurrentFont,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 1001
        }), "DarkText")
        messageY = 35
    end

    InsertTheme(Create("TextLabel", Card, {
        Size = UDim2.new(1, -(textX + 12), 0, NOTIFY_HEIGHT - messageY - 6),
        Position = UDim2.new(0, textX, 0, messageY),
        BackgroundTransparency = 1,
        Text = tostring(Opts.Message or ""),
        TextColor3 = Theme["Color Dark Text"],
        Font = MyLibrary.CurrentFont,
        TextSize = 10,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        TextTruncate = Enum.TextTruncate.AtEnd,
        ZIndex = 1001
    }), "DarkText")

    local CloseButton = InsertTheme(Create("TextButton", Card, {
        Size = UDim2.new(0, 24, 0, 24),
        Position = UDim2.new(1, -3, 0, 3),
        AnchorPoint = Vector2.new(1, 0),
        BackgroundTransparency = 1,
        Text = "X",
        TextColor3 = Theme["Color Dark Text"],
        Font = Enum.Font.GothamBold,
        TextSize = 12,
        AutoButtonColor = false,
        ZIndex = 1002
    }), "DarkText")

    -- barra de tempo
    local Progress = InsertTheme(Create("Frame", Card, {
        Size = UDim2.new(1, 0, 0, 2),
        Position = UDim2.new(0, 0, 1, -2),
        BackgroundColor3 = Theme["Color Theme"],
        BorderSizePixel = 0,
        ZIndex = 1001
    }), "Theme")

    local closed = false
    local Notification = {}

    function Notification.Close()
        if closed then return end
        closed = true

        local index = table.find(ActiveNotifications, Notification)
        if index then table.remove(ActiveNotifications, index) end

        CreateTween({Card, "Position", UDim2.new(0, NOTIFY_HIDDEN_X, 0, 0), 0.25, true})
        CreateTween({Slot, "Size", UDim2.new(0, NOTIFY_WIDTH, 0, 0), 0.15, true})
        Slot:Destroy()
    end

    table.insert(ActiveNotifications, Notification)
    CloseButton.Activated:Connect(Notification.Close)

    CreateTween({Card, "Position", UDim2.new(0, 0, 0, 0), 0.35})
    pcall(function()
        TweenService:Create(Progress, TweenInfo.new(Duration, Enum.EasingStyle.Linear), {
            Size = UDim2.new(0, 0, 0, 2)
        }):Play()
    end)
    task.delay(Duration, Notification.Close)

    return Notification
end

function MyLibrary:Notify(Configs)
    Configs = Configs or {}
    return BuildNotification({
        Title = Configs.Title or Configs.Name or Configs[1] or "Notificacao",
        Message = Configs.Message or Configs.Text or Configs[2] or "",
        Duration = Configs.Duration or Configs.Time or Configs[3] or 4
    })
end

function MyLibrary:NotifyWithImage(Configs)
    Configs = Configs or {}
    return BuildNotification({
        Title = Configs.Title or Configs.Name or Configs[1] or "Notificacao",
        SubTitle = Configs.SubTitle or Configs.Sub or Configs[2] or "",
        Message = Configs.Message or Configs.Text or Configs[3] or "",
        Image = Configs.Image or Configs.Icon or Configs[4] or "rbxassetid://86050226751861",
        Duration = Configs.Duration or Configs.Time or Configs[5] or 4
    })
end

----------------------------------------------------------------------
-- INTRO (loadstring carregado antes do resto do hub)
----------------------------------------------------------------------
MyLibrary.IntroSource = DEFAULT_INTRO

function MyLibrary:SetIntro(source)
    MyLibrary.IntroSource = source
end

function MyLibrary:GetIntroEnabled()
    return MyLibrary.Save.IntroEnabled ~= false
end

function MyLibrary:SetIntroEnabled(enabled)
    enabled = enabled == true
    if MyLibrary.Save.IntroEnabled == enabled then return end
    MyLibrary.Save.IntroEnabled = enabled
    SaveLib()
end

-- source pode ser: link (string), codigo Lua (string) ou funcao
local function RunIntro(source)
    if MyLibrary.Save.IntroEnabled == false then return false end
    if source == nil or source == "" then return false end

    task.spawn(function()
        local ok, err = pcall(function()
            if type(source) == "function" then
                source()
            elseif type(source) == "string" then
                local code = source
                if source:match("^https?://") then
                    code = game:HttpGet(source)
                end
                local fn = loadstring(code)
                if fn then fn() end
            end
        end)
        if not ok then warn("[Intro] Erro: " .. tostring(err)) end
    end)
    return true
end

----------------------------------------------------------------------
-- CONFIGURACAO NA CRIACAO DA JANELA (pasta / nome do ScreenGui)
----------------------------------------------------------------------
local function ConfigureLibFolder(name)
    if type(name) ~= "string" or name:gsub("%s", "") == "" or name == LibFolder then return end

    LibFolder = name
    IMAGES_FOLDER = LibFolder .. "/imagens"
    JSON_FILE_PATH = IMAGES_FOLDER .. "/imagens.json"
    IMAGE_FILES.Hub = IMAGES_FOLDER .. "/ImageHub.png"
    IMAGE_FILES.Topbar = IMAGES_FOLDER .. "/ImageTopbar.png"
    IMAGE_FILES.Minimize = IMAGES_FOLDER .. "/ImageMinimize.png"

    SafeMakeFolder(LibFolder)
    SafeMakeFolder(IMAGES_FOLDER)

    -- recarrega tudo que estava salvo na nova pasta
    pcall(LoadLibSettings, LIB_JSON)

    local base = OriginalThemes[MyLibrary.Save.Theme]
    local cur = MyLibrary.Themes[MyLibrary.Save.Theme]
    if base and cur then
        for k, v in pairs(base) do cur[k] = v end
    end
    Theme = cur
    ApplyCustomColorsToTheme(Theme)

    ClickSoundEnabled = MyLibrary.Save.ClickSoundEnabled or false
    ClickSoundId = MyLibrary.Save.ClickSoundId or "rbxassetid://18998603679"
    ClickSoundVolume = MyLibrary.Save.ClickSoundVolume or 0.1

    CurrentImageSettings = LoadImageSettings()
    LastImageLinks.Hub = CurrentImageSettings.HubImage
    LastImageLinks.Minimize = CurrentImageSettings.MinimizeImage
    LastImageLinks.Topbar = CurrentImageSettings.TopbarImage

    Translation.Language = DetectLanguage()
end

local function ConfigureScreenGuiName(name)
    if type(name) ~= "string" or name:gsub("%s", "") == "" or name == ScreenGui.Name then return end

    -- remove copias antigas com o mesmo nome
    for _, parent in ipairs({GuiParent, CoreGui}) do
        pcall(function()
            for _, child in ipairs(parent:GetChildren()) do
                if child ~= ScreenGui and child.Name == name and child:IsA("ScreenGui") then
                    child:Destroy()
                end
            end
        end)
    end
    ScreenGui.Name = name
end

