function MyLibrary:MakeWindow(Configs)
    Configs = Configs or {}
    local WTitle = Configs[1] or Configs.Name or Configs.Title or "SAGAZx"
    local WMiniText = Configs[2] or Configs.SubTitle or "by : SAGAZx"

    -- configuracoes feitas na criacao (todas opcionais)
    ConfigureLibFolder(Configs.Folder or Configs.LibFolder)
    ConfigureScreenGuiName(Configs.ScreenGui or Configs.ScreenGuiName)

    -- Intro: comeca 0.5s antes do resto do hub carregar (se estiver ligada nas configuracoes)
    local IntroSource = Configs.Intro or Configs.IntroLink or Configs.Introducao or MyLibrary.IntroSource
    if RunIntro(IntroSource) then task.wait(0.5) end

    -- Janela de update (aparece so uma vez por conteudo; mudou o texto, aparece de novo)
    local UpdateCfg = Configs.Update or Configs.Updates or Configs.Atualizacao

    Settings.ScriptFile = Configs[3] or Configs.SaveFolder or false

    local TranslationSource = Configs.Traducoes or Configs.Translations or Configs.Translation
        or Configs["Traduções"] or Configs.TranslationLink or Translation.Link

    local function LoadFile()
        local File = Settings.ScriptFile
        if type(File) ~= "string" then return end
        local path = GetFullPath(File)
        if not readfile or not isfile then return end
        local s, r = pcall(isfile, path)
        if s and r then
            local s2, content = pcall(readfile, path)
            if s2 and type(content) == "string" then
                local s3, decoded = pcall(function() return HttpService:JSONDecode(content) end)
                Flags = (s3 and type(decoded) == "table") and decoded or {}
            end
        end
    end
    LoadFile()

