    end

    ------------------------------------------------------------------
    -- COMPONENTES COMUNS (secao, paragrafo, musica, botao, toggle, keybind)
    ------------------------------------------------------------------
    local AttachElements, AttachExtras -- definidas mais abaixo

    local ARROW_DOWN, ARROW_UP = "rbxassetid://10709791523", "rbxassetid://10709790948"

    local function AttachCommon(Tab, Container, Ctx)
        -- Secao: titulo simples. Se voce adicionar componentes nela
        -- (Section:AddButton, Section:AddToggle...), ela vira expansivel.
        function Tab:AddSection(Cfg)
            local SectionName, StartOpen = "Section", true
            if type(Cfg) == "string" then
                SectionName = Cfg
            elseif type(Cfg) == "table" then
                SectionName = Cfg[1] or Cfg.Name or Cfg.Title or Cfg.Section or "Section"
                local o = Cfg.Open
                if o == nil then o = Cfg.Opened end
                if o == nil then o = Cfg.Default end
                if o ~= nil then StartOpen = o == true end
            end

            local SectionFrame = Create("Frame", Container, {
                Size = UDim2.new(1, 0, 0, 22),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                Name = "Option"
            }, {
                Create("UIListLayout", {
                    SortOrder = Enum.SortOrder.LayoutOrder,
                    Padding = UDim.new(0, 5)
                })
            })

            local Header = Create("TextButton", SectionFrame, {
                Size = UDim2.new(1, 0, 0, 22),
                BackgroundTransparency = 1,
                AutoButtonColor = false,
                Text = "",
                LayoutOrder = 0,
                Name = "SectionHeader"
            })

            local SectionLabel = InsertTheme(Create("TextLabel", Header, {
                Font = MyLibrary.CurrentFont,
                Text = SectionName,
                TextColor3 = Theme["Color Text"],
                Size = UDim2.new(1, -30, 1, 0),
                Position = UDim2.new(0, 5, 0, 0),
                BackgroundTransparency = 1,
                TextTruncate = "AtEnd",
                TextSize = 11,
                TextXAlignment = "Left"
            }), "Text")

            local HasChildren = false
            local Opened = StartOpen

            local Arrow = InsertTheme(Create("ImageLabel", Header, {
                Size = UDim2.new(0, 14, 0, 14),
                Position = UDim2.new(1, -6, 0.5, 0),
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundTransparency = 1,
                Image = ARROW_DOWN,
                ImageColor3 = Theme["Color Theme"],
                Rotation = StartOpen and 0 or -90,
                Visible = false
            }), "Theme")

            local Content = Create("Frame", SectionFrame, {
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                LayoutOrder = 1,
                Visible = StartOpen,
                Name = "SectionContent"
            }, {
                Create("UIListLayout", {
                    SortOrder = Enum.SortOrder.LayoutOrder,
                    Padding = UDim.new(0, 5)
                }),
                Create("UIPadding", { PaddingLeft = UDim.new(0, 6) })
            })

            local function SetOpen(Bool)
                Opened = Bool == true
                Content.Visible = Opened
                CreateTween({Arrow, "Rotation", Opened and 0 or -90, 0.2})
            end

            Content.ChildAdded:Connect(function(child)
                if child:IsA("GuiObject") and not HasChildren then
                    HasChildren = true
                    Arrow.Visible = true
                end
            end)

            Header.Activated:Connect(function()
                if HasChildren then SetOpen(not Opened) end
            end)

            local Section = {}
            -- componentes dentro da secao
            AttachElements(Section, Content, Ctx)

            table.insert(MyLibrary.Options, {type = "Section", Name = SectionName, func = Section})
            function Section:Visible(Bool) Funcs:ToggleVisible(SectionFrame, Bool) end
            function Section:Destroy() SectionFrame:Destroy() end
            function Section:Set(New)
                if New then SectionLabel.Text = GetStr(New) end
            end
            function Section:Open() SetOpen(true) end
            function Section:Close() SetOpen(false) end
            function Section:Toggle() SetOpen(not Opened) end
            function Section:IsOpen() return Opened end
            return Section
        end

        function Tab:AddParagraph(Cfg)
            local PName = Cfg[1] or Cfg.Title or "Paragraph"
            local PDesc = Cfg[2] or Cfg.Text or ""

            local Frame, LabelFunc = ButtonFrame(Container, PName, PDesc, UDim2.new(1, -20))

            local Paragraph = {}
            function Paragraph:Visible(...) Funcs:ToggleVisible(Frame, ...) end
            function Paragraph:Destroy() Frame:Destroy() end
            function Paragraph:SetTitle(Val) LabelFunc:SetTitle(GetStr(Val)) end
            function Paragraph:SetDesc(Val) LabelFunc:SetDesc(GetStr(Val)) end
            function Paragraph:Set(Val1, Val2)
                if Val1 and Val2 then
                    LabelFunc:SetTitle(GetStr(Val1))
                    LabelFunc:SetDesc(GetStr(Val2))
                elseif Val1 then
                    LabelFunc:SetDesc(GetStr(Val1))
                end
            end
            return Paragraph
        end

        function Tab:AddMusicPlayer(Cfg)
            Cfg = Cfg or {}
            local PTitle = Cfg.Title or Cfg.Name or Cfg[1] or "Music Player"
            local PArtist = Cfg.Artist or Cfg.Desc or Cfg.Description or ""

            local IMG = {
                Play = "rbxassetid://8517323790",
                Pause = "rbxassetid://130857109630735",
                Previous = "rbxassetid://18802845025",
                Next = "rbxassetid://11283329347",
                Repeat = "rbxassetid://121565343679841",
                Stop = "rbxassetid://116155660929916",
                RepeatOne = "rbxassetid://101892266050705",
            }

            local function fire(name, ...)
                local f = Cfg[name]
                if type(f) == "function" then task.spawn(f, ...) end
            end

            local function ParseMode(v)
                if type(v) == "boolean" then return v end
                if type(v) == "string" then return v:lower() == "local" end
                return nil
            end

            local function SnapVol(v)
                v = tonumber(v) or 50
                return math.clamp(math.floor(v / 5 + 0.5) * 5, 5, 100)
            end

            local function CleanId(id)
                return (tostring(id):gsub("rbxassetid://", ""):gsub("%s", ""))
            end

            local function FormatTime(t)
                t = math.max(0, math.floor(t or 0))
                return string.format("%02d:%02d", math.floor(t / 60), t % 60)
            end

            -- estado
            local cfgMode = ParseMode(Cfg.Mode)
            local isLocal = cfgMode == true
            local locked = cfgMode ~= nil and Cfg.Lock ~= false
            local volume = SnapVol(Cfg.Volume or 50)
            local playing, stopped = false, true
            local repeatIdx = 1
            local RepeatStates = {"Off", "All", "One"}
            local current, tracks = nil, {}
            local duration, position = 0, 0
            local conns = {}

            -- som (criado novo a cada musica)
            local Snd, endConn

            local function ApplyVolume()
                if Snd then Snd.Volume = isLocal and (volume / 100) or 0 end
            end

            ------------------------------------------------------------------
            -- QUADRO
            ------------------------------------------------------------------
            local Frame = InsertTheme(Create("Frame", Container, {
                Size = UDim2.new(1, 0, 0, 134),
                BackgroundColor3 = Theme["Color Hub 2"],
                Name = "Option"
            }), "Frame")
            AddTransparency(Frame)
            Make("Corner", Frame, UDim.new(0, 6))
            ApplyBorder(Frame)

            local TitleLabel = InsertTheme(Create("TextLabel", Frame, {
                Size = UDim2.new(1, -120, 0, 16),
                Position = UDim2.new(0, 10, 0, 6),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = PTitle,
                TextColor3 = Theme["Color Text"],
                TextSize = 12,
                TextXAlignment = "Left",
                TextTruncate = "AtEnd"
            }), "Text")

            local ArtistLabel = InsertTheme(Create("TextLabel", Frame, {
                Size = UDim2.new(1, -120, 0, 12),
                Position = UDim2.new(0, 10, 0, 23),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = PArtist,
                TextColor3 = Theme["Color Dark Text"],
                TextSize = 9,
                TextXAlignment = "Left",
                TextTruncate = "AtEnd"
            }), "DarkText")

            ------------------------------------------------------------------
            -- TOGGLE REMOTE / LOCAL
            ------------------------------------------------------------------
            local ApplyMode -- definido mais abaixo

            local ModeArea = Create("Frame", Frame, {
                Size = UDim2.new(0, 100, 0, 16),
                Position = UDim2.new(1, -10, 0, 8),
                AnchorPoint = Vector2.new(1, 0),
                BackgroundTransparency = 1
            })

            local ModeLabel = InsertTheme(Create("TextLabel", ModeArea, {
                Size = UDim2.new(1, -32, 1, 0),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = "REMOTE",
                TextColor3 = Theme["Color Theme"],
                TextSize = 10,
                TextXAlignment = "Right"
            }), "Theme")

            local ModeHolder = InsertTheme(Create("Frame", ModeArea, {
                Size = UDim2.new(0, 26, 0, 13),
                Position = UDim2.new(1, 0, 0.5, 0),
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundColor3 = Theme["Color Stroke"]
            }), "Stroke")
            AddTransparency(ModeHolder)
            Make("Corner", ModeHolder, UDim.new(0.5, 0))

            local ModeSlider = Create("Frame", ModeHolder, {
                BackgroundTransparency = 1,
                Size = UDim2.new(0.8, 0, 0.8, 0),
                Position = UDim2.new(0.5, 0, 0.5, 0),
                AnchorPoint = Vector2.new(0.5, 0.5)
            })

            local ModeKnob = InsertTheme(Create("Frame", ModeSlider, {
                Size = UDim2.new(0, 9, 0, 9),
                Position = UDim2.new(0, 0, 0.5, 0),
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundColor3 = Theme["Color Theme"],
                BackgroundTransparency = 0.8
            }), "Theme")
            Make("Corner", ModeKnob, UDim.new(0.5, 0))

            local ModeButton = Create("TextButton", ModeArea, {
                Size = UDim2.new(1, 0, 1, 0),
                BackgroundTransparency = 1,
                Text = "",
                ZIndex = 5
            })

            local function UpdateModeUI(instant)
                ModeLabel.Text = isLocal and "Free(local)" or "Gamepass"
                ModeLabel.TextTransparency = locked and 0.4 or 0
                local pos = isLocal and UDim2.new(1, 0, 0.5, 0) or UDim2.new(0, 0, 0.5, 0)
                local anchor = isLocal and Vector2.new(1, 0.5) or Vector2.new(0, 0.5)
                local transp = isLocal and 0 or 0.8
                if instant then
                    ModeKnob.Position, ModeKnob.AnchorPoint, ModeKnob.BackgroundTransparency = pos, anchor, transp
                else
                    CreateTween({ModeKnob, "Position", pos, 0.25})
                    CreateTween({ModeKnob, "AnchorPoint", anchor, 0.25})
                    CreateTween({ModeKnob, "BackgroundTransparency", transp, 0.25})
                end
            end
            UpdateModeUI(true)

            ModeButton.Activated:Connect(function()
                if locked then return end -- modo travado na criacao
                ApplyMode(not isLocal)
            end)

            ------------------------------------------------------------------
            -- BARRAS (progresso e volume)
            ------------------------------------------------------------------
            local function MakeBar(Parent, Pos, Size)
                local Holder = Create("TextButton", Parent, {
                    Size = Size,
                    Position = Pos,
                    BackgroundTransparency = 1,
                    AutoButtonColor = false,
                    Text = ""
                })
                local Bar = InsertTheme(Create("Frame", Holder, {
                    BackgroundColor3 = Theme["Color Stroke"],
                    Size = UDim2.new(1, 0, 0, 5),
                    Position = UDim2.new(0.5, 0, 0.5, 0),
                    AnchorPoint = Vector2.new(0.5, 0.5)
                }), "Stroke")
                AddTransparency(Bar)
                Make("Corner", Bar)

                local Ind = InsertTheme(Create("Frame", Bar, {
                    BackgroundColor3 = Theme["Color Theme"],
                    Size = UDim2.fromScale(0, 1),
                    BorderSizePixel = 0
                }), "Theme")
                Make("Corner", Ind)

                local Icon = Create("Frame", Bar, {
                    Size = UDim2.new(0, 6, 0, 12),
                    BackgroundColor3 = Color3.fromRGB(220, 220, 220),
                    Position = UDim2.fromScale(0, 0.5),
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundTransparency = 0.2
                })
                Make("Corner", Icon)

                local function SetVisual(f)
                    f = math.clamp(f, 0, 1)
                    Ind.Size = UDim2.new(f, 0, 1, 0)
                    Icon.Position = UDim2.new(f, 0, 0.5, 0)
                end
                return Holder, Bar, SetVisual
            end

            local function BindBar(Holder, Bar, OnMove, OnEnd)
                local state = {dragging = false}
                local act, last = nil, 0

                local function frac(x)
                    return math.clamp((x - Bar.AbsolutePosition.X) / math.max(Bar.AbsoluteSize.X, 1), 0, 1)
                end

                Holder.InputBegan:Connect(function(Input)
                    if not IsPress(Input) then return end
                    state.dragging, act = true, Input
                    local scroller = GetScroller(Container)
                    if scroller then scroller.ScrollingEnabled = false end
                    last = frac(Input.Position.X)
                    OnMove(last)
                end)

                table.insert(conns, Track(UserInputService.InputChanged:Connect(function(Input)
                    if not state.dragging then return end
                    if Input.UserInputType == Enum.UserInputType.MouseMovement
                        or (Input.UserInputType == Enum.UserInputType.Touch and Input == act) then
                        last = frac(Input.Position.X)
                        OnMove(last)
                    end
                end)))

                table.insert(conns, Track(UserInputService.InputEnded:Connect(function(Input)
                    if state.dragging and (Input == act or Input.UserInputType == Enum.UserInputType.MouseButton1) then
                        state.dragging, act = false, nil
                        local scroller = GetScroller(Container)
                        if scroller then scroller.ScrollingEnabled = true end
                        OnEnd(last)
                    end
                end)))

                return state
            end

            -- progresso
            local ProgHolder, ProgBar, SetProgVisual = MakeBar(Frame, UDim2.new(0, 10, 0, 40), UDim2.new(1, -20, 0, 16))
            local ProgState

            local CurTime = InsertTheme(Create("TextLabel", Frame, {
                Size = UDim2.new(0, 45, 0, 10),
                Position = UDim2.new(0, 10, 0, 57),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = "00:00",
                TextColor3 = Theme["Color Dark Text"],
                TextSize = 8,
                TextXAlignment = "Left"
            }), "DarkText")

            local TotTime = InsertTheme(Create("TextLabel", Frame, {
                Size = UDim2.new(0, 45, 0, 10),
                Position = UDim2.new(1, -10, 0, 57),
                AnchorPoint = Vector2.new(1, 0),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = "00:00",
                TextColor3 = Theme["Color Dark Text"],
                TextSize = 8,
                TextXAlignment = "Right"
            }), "DarkText")

            local function UpdateProgress(pos, dur)
                duration = math.max(0, dur or duration)
                position = math.clamp(pos or position, 0, duration)
                TotTime.Text = FormatTime(duration)
                if ProgState and ProgState.dragging then return end
                CurTime.Text = FormatTime(position)
                SetProgVisual(duration > 0 and position / duration or 0)
            end

            -- volume
            InsertTheme(Create("TextLabel", Frame, {
                Size = UDim2.new(0, 28, 0, 16),
                Position = UDim2.new(0, 10, 0, 112),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = "VOL",
                TextColor3 = Theme["Color Dark Text"],
                TextSize = 9,
                TextXAlignment = "Left"
            }), "DarkText")

            local VolValue = InsertTheme(Create("TextLabel", Frame, {
                Size = UDim2.new(0, 34, 0, 16),
                Position = UDim2.new(1, -10, 0, 112),
                AnchorPoint = Vector2.new(1, 0),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = tostring(volume),
                TextColor3 = Theme["Color Text"],
                TextSize = 9,
                TextXAlignment = "Right"
            }), "Text")

            local VolHolder, VolBar, SetVolVisual = MakeBar(Frame, UDim2.new(0, 40, 0, 112), UDim2.new(1, -90, 0, 16))

            local function SetVolume(v)
                volume = SnapVol(v)
                VolValue.Text = tostring(volume)
                SetVolVisual((volume - 5) / 95)
                ApplyVolume()
            end
            SetVolume(volume)

            BindBar(VolHolder, VolBar,
                function(f) SetVolume(5 + math.floor(f * 19 + 0.5) * 5) end,
                function()
                    if not isLocal then fire("RemoteVolume", volume) end
                    fire("OnVolume", volume)
                end
            )

            ------------------------------------------------------------------
            -- BOTOES
            ------------------------------------------------------------------
            local Row = Create("Frame", Frame, {
                Size = UDim2.new(1, 0, 0, 36),
                Position = UDim2.new(0, 0, 0, 71),
                BackgroundTransparency = 1
            }, {
                Create("UIListLayout", {
                    FillDirection = "Horizontal",
                    HorizontalAlignment = "Center",
                    VerticalAlignment = "Center",
                    SortOrder = "LayoutOrder",
                    Padding = UDim.new(0, 14)
                })
            })

            local function IconButton(order, image, size)
                return InsertTheme(Create("ImageButton", Row, {
                    Size = UDim2.fromOffset(size, size),
                    BackgroundTransparency = 1,
                    AutoButtonColor = false,
                    Image = image,
                    ImageColor3 = Theme["Color Text"],
                    LayoutOrder = order
                }), "Text")
            end

            local RepeatBtn = IconButton(1, IMG.Repeat, 20)
            local PrevBtn = IconButton(2, IMG.Previous, 22)

            local PlayCircle = InsertTheme(Create("Frame", Row, {
                Size = UDim2.fromOffset(34, 34),
                BackgroundColor3 = Theme["Color Stroke"],
                LayoutOrder = 3
            }), "Stroke")
            AddTransparency(PlayCircle)
            Make("Corner", PlayCircle, UDim.new(0.5, 0))
            ApplyBorder(PlayCircle)

            local PlayIcon = InsertTheme(Create("ImageLabel", PlayCircle, {
                Size = UDim2.fromOffset(18, 18),
                Position = UDim2.fromScale(0.5, 0.5),
                AnchorPoint = Vector2.new(0.5, 0.5),
                BackgroundTransparency = 1,
                Image = IMG.Play,
                ImageColor3 = Theme["Color Text"]
            }), "Text")

            local PlayBtn = Create("TextButton", PlayCircle, {
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                Text = "",
                ZIndex = 5
            })

            local NextBtn = IconButton(4, IMG.Next, 22)
            local StopBtn = IconButton(5, IMG.Stop, 20)

            local function UpdatePlayIcon()
                PlayIcon.Image = playing and IMG.Pause or IMG.Play
            end

            local function UpdateRepeatUI()
                local state = RepeatStates[repeatIdx]
                RepeatBtn.Image = state == "One" and IMG.RepeatOne or IMG.Repeat
                CreateTween({RepeatBtn, "ImageTransparency", state == "Off" and 0.6 or 0, 0.2})
            end
            UpdateRepeatUI()

            ------------------------------------------------------------------
            -- MOTOR DO PLAYER
            ------------------------------------------------------------------
            local gen, handledGen = 0, -1
            local startClock, pausedAt, pausedTotal = 0, nil, 0

            local function KillSound()
                if endConn then endConn:Disconnect() endConn = nil end
                if Snd then
                    local old = Snd
                    Snd = nil
                    pcall(function() old:Stop() old:Destroy() end)
                end
            end
            ScreenGui.Destroying:Connect(KillSound)

            local function FindIndex(id)
                for i, t in ipairs(tracks) do
                    if t.id == id then return i end
                end
            end

            local PlayTrack, StopPlayer, PausePlayer, ResumePlayer, HandleEnd

            local function NewSound(id, myGen)
                KillSound()
                local s = Instance.new("Sound")
                s.Name = "SAGAZ_MusicPlayer"
                s.Looped = false
                s.SoundId = "rbxassetid://" .. id
                s.Volume = isLocal and (volume / 100) or 0
                s.Parent = SoundService
                Snd = s
                endConn = s.Ended:Connect(function()
                    if myGen == gen then HandleEnd(myGen) end
                end)
                s:Play()
            end

            PlayTrack = function(id, name, replay)
                id = CleanId(id)
                if id == "" then return end

                local idx = FindIndex(id)
                if not name then
                    name = idx and tracks[idx].name or ("Musica " .. id)
                end

                gen = gen + 1
                local myGen = gen

                current = {id = id, name = name}
                TitleLabel.Text = name
                ArtistLabel.Text = "ID: " .. id

                NewSound(id, myGen)

                playing, stopped = true, false
                startClock, pausedAt, pausedTotal = os.clock(), nil, 0
                UpdatePlayIcon()
                UpdateProgress(0, 0)

                if not isLocal then
                    if replay then
                        -- mesmo ID de novo: para e toca de novo pra reiniciar no servidor
                        fire("RemoteStop")
                        task.delay(0.5, function()
                            if gen == myGen and not isLocal and not stopped then
                                fire("RemotePlay", id)
                            end
                        end)
                    else
                        fire("RemotePlay", id)
                    end
                end
                fire("OnPlay", id, name)
            end

            StopPlayer = function(skipRemote)
                gen = gen + 1
                KillSound()
                playing, stopped = false, true
                UpdatePlayIcon()
                UpdateProgress(0, 0)
                if not isLocal and not skipRemote then fire("RemoteStop") end
                fire("OnStop")
            end

            PausePlayer = function()
                if not current or stopped or not playing then return end
                if Snd then Snd:Pause() end
                pausedAt = os.clock()
                playing = false
                UpdatePlayIcon()
                if not isLocal then fire("RemotePause") end
                fire("OnPause")
            end

            ResumePlayer = function()
                if not current or stopped or playing then return end
                if Snd then Snd:Resume() end
                if pausedAt then pausedTotal = pausedTotal + (os.clock() - pausedAt) pausedAt = nil end
                playing = true
                UpdatePlayIcon()
                if not isLocal then fire("RemoteResume") end
                fire("OnPlay", current.id, current.name)
            end

            local function TogglePlay()
                if playing then
                    PausePlayer()
                elseif current and not stopped then
                    ResumePlayer()
                elseif current then
                    PlayTrack(current.id, current.name)
                elseif tracks[1] then
                    PlayTrack(tracks[1].id, tracks[1].name)
                end
            end

            local function NextTrack()
                if #tracks == 0 then return end
                local idx = current and FindIndex(current.id) or 0
                local t = tracks[(idx or 0) % #tracks + 1]
                PlayTrack(t.id, t.name)
                fire("OnNext")
            end

            local function PrevTrack()
                if #tracks == 0 then
                    if current then PlayTrack(current.id, current.name) end
                    return
                end
                local idx = current and FindIndex(current.id)
                local t = idx and tracks[(idx - 2) % #tracks + 1] or tracks[#tracks]
                PlayTrack(t.id, t.name)
                fire("OnPrevious")
            end

            -- fim da musica (Ended ou plano B do Heartbeat; so roda 1x por musica)
            HandleEnd = function(myGen)
                if myGen ~= gen or handledGen == myGen or not current then return end
                handledGen = myGen

                local rep = RepeatStates[repeatIdx]
                if rep == "One" then
                    PlayTrack(current.id, current.name, true)
                    return
                end

                local idx = FindIndex(current.id)
                if idx and idx < #tracks then
                    local t = tracks[idx + 1]
                    PlayTrack(t.id, t.name)
                elseif rep == "All" then
                    if idx and #tracks > 0 then
                        local t = tracks[1]
                        PlayTrack(t.id, t.name, t.id == current.id)
                    else
                        PlayTrack(current.id, current.name, true)
                    end
                else
                    StopPlayer(true)
                end
            end

            ApplyMode = function(newLocal)
                newLocal = newLocal == true
                if newLocal == isLocal then return end

                local wasActive = current ~= nil and not stopped
                if not isLocal and current then fire("RemoteStop") end -- saindo do remote

                isLocal = newLocal
                UpdateModeUI()
                ApplyVolume()

                if wasActive then
                    if playing then
                        PlayTrack(current.id, current.name) -- recomeca no novo modo
                    else
                        StopPlayer(true)
                    end
                end
                fire("OnModeChanged", isLocal)
            end

            -- atualiza barra e contador
            table.insert(conns, Track(RunService.Heartbeat:Connect(function()
                if not current or stopped or not Snd then return end

                local len = Snd.TimeLength
                if len > 0 then
                    UpdateProgress(Snd.TimePosition, len)
                    if playing and Snd.TimePosition >= len - 0.05 then
                        HandleEnd(gen)
                    end
                elseif not (ProgState and ProgState.dragging) then
                    -- audio ainda carregando / nao carregou: conta o tempo
                    local el = (pausedAt or os.clock()) - startClock - pausedTotal
                    CurTime.Text = FormatTime(el)
                end
            end)))

            -- seek (so no modo local; no remote nao da pra pular)
            ProgState = BindBar(ProgHolder, ProgBar,
                function(f)
                    SetProgVisual(f)
                    CurTime.Text = FormatTime(f * duration)
                end,
                function(f)
                    if isLocal and Snd and current and not stopped and duration > 0 then
                        Snd.TimePosition = f * duration
                        fire("OnSeek", f * duration)
                    end
                end
            )

            PlayBtn.Activated:Connect(TogglePlay)
            PrevBtn.Activated:Connect(PrevTrack)
            NextBtn.Activated:Connect(NextTrack)
            StopBtn.Activated:Connect(function() StopPlayer() end)
            RepeatBtn.Activated:Connect(function()
                repeatIdx = repeatIdx % #RepeatStates + 1
                UpdateRepeatUI()
                fire("OnRepeat", RepeatStates[repeatIdx])
            end)

            UpdateProgress(0, 0)

            ------------------------------------------------------------------
            -- API
            ------------------------------------------------------------------
            local MusicPlayer = {}
            function MusicPlayer:Play(id, name) PlayTrack(id, name) end
            function MusicPlayer:Stop() StopPlayer() end
            function MusicPlayer:Pause() PausePlayer() end
            function MusicPlayer:Resume() ResumePlayer() end
            function MusicPlayer:Toggle() TogglePlay() end
            function MusicPlayer:Next() NextTrack() end
            function MusicPlayer:Previous() PrevTrack() end

            function MusicPlayer:AddTrack(name, id)
                id = CleanId(id)
                if id == "" or FindIndex(id) then return end
                table.insert(tracks, {id = id, name = tostring(name or ("Musica " .. id))})
            end
            function MusicPlayer:ClearTracks() table.clear(tracks) end

            function MusicPlayer:SetLocal(v) ApplyMode(v) end
            function MusicPlayer:SetMode(m)
                local v = ParseMode(m)
                if v ~= nil then ApplyMode(v) end
            end
            function MusicPlayer:GetMode() return isLocal and "Local" or "Remote" end
            function MusicPlayer:IsLocal() return isLocal end
            function MusicPlayer:IsLocked() return locked end

            function MusicPlayer:SetVolume(v)
                SetVolume(v)
                if not isLocal then fire("RemoteVolume", volume) end
            end
            function MusicPlayer:GetVolume() return volume end

            function MusicPlayer:SetTitle(t) TitleLabel.Text = tostring(GetStr(t) or "") end
            function MusicPlayer:SetArtist(t) ArtistLabel.Text = tostring(GetStr(t) or "") end
            function MusicPlayer:SetRepeat(state)
                local idx = table.find(RepeatStates, state)
                if idx then repeatIdx = idx UpdateRepeatUI() end
            end
            function MusicPlayer:GetRepeat() return RepeatStates[repeatIdx] end
            function MusicPlayer:IsPlaying() return playing end
            function MusicPlayer:Visible(...) Funcs:ToggleVisible(Frame, ...) end
            function MusicPlayer:Destroy()
                for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
                KillSound()
                Frame:Destroy()
            end

            return MusicPlayer
        end

        function Tab:AddButton(Cfg)
            local BName = Cfg[1] or Cfg.Name or Cfg.Title or "Button!"
            local BDescription = Cfg.Desc or Cfg.Description or ""
            local Callback = Funcs:GetCallback(Cfg, 2)

            local FButton, LabelFunc = ButtonFrame(Container, BName, BDescription, UDim2.new(1, -20))

            Create("ImageLabel", FButton, {
                Size = UDim2.new(0, 14, 0, 14),
                Position = UDim2.new(1, -10, 0.5),
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundTransparency = 1,
                Image = "rbxassetid://10734973999"
            })

            FButton.Activated:Connect(function()
                Funcs:FireCallback(Callback)
            end)

            local Button = {}
            function Button:Visible(...) Funcs:ToggleVisible(FButton, ...) end
            function Button:Destroy() FButton:Destroy() end
            function Button:Callback(...) Funcs:InsertCallback(Callback, ...) end
            function Button:Set(Val1, Val2)
                if type(Val1) == "string" and type(Val2) == "string" then
                    LabelFunc:SetTitle(Val1)
                    LabelFunc:SetDesc(Val2)
                elseif type(Val1) == "string" then
                    LabelFunc:SetTitle(Val1)
                elseif type(Val1) == "function" then
                    table.clear(Callback)
                    table.insert(Callback, Val1)
                end
            end
            return Button
        end

        function Tab:AddToggle(Cfg)
            local TName = Cfg[1] or Cfg.Name or Cfg.Title or "Toggle"
            local TDesc = Cfg.Desc or Cfg.Description or ""
            local Callback = Funcs:GetCallback(Cfg, 3)
            local Flag = Cfg[4] or Cfg.Flag or false
            local Default = Cfg[2] or Cfg.Default or false
            if CheckFlag(Flag) then Default = GetFlag(Flag) end

            local Button, LabelFunc = ButtonFrame(Container, TName, TDesc, UDim2.new(1, -38))

            local ToggleHolder = InsertTheme(Create("Frame", Button, {
                Size = UDim2.new(0, 35, 0, 18),
                Position = UDim2.new(1, -10, 0.5),
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundColor3 = Theme["Color Stroke"]
            }), "Stroke")
            AddTransparency(ToggleHolder)
            Make("Corner", ToggleHolder, UDim.new(0.5, 0))

            local Slider = Create("Frame", ToggleHolder, {
                BackgroundTransparency = 1,
                Size = UDim2.new(0.8, 0, 0.8, 0),
                Position = UDim2.new(0.5, 0, 0.5, 0),
                AnchorPoint = Vector2.new(0.5, 0.5)
            })

            local Toggle = InsertTheme(Create("Frame", Slider, {
                Size = UDim2.new(0, 12, 0, 12),
                Position = UDim2.new(0, 0, 0.5),
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundColor3 = Theme["Color Theme"]
            }), "Theme")
            Make("Corner", Toggle, UDim.new(0.5, 0))

            local function SetToggle(Val)
                Default = Val == true
                SetFlag(Flag, Default)
                Funcs:FireCallback(Callback, Default)
                if Default then
                    CreateTween({Toggle, "Position", UDim2.new(1, 0, 0.5), 0.25})
                    CreateTween({Toggle, "BackgroundTransparency", 0, 0.25})
                    CreateTween({Toggle, "AnchorPoint", Vector2.new(1, 0.5), 0.25})
                else
                    CreateTween({Toggle, "Position", UDim2.new(0, 0, 0.5), 0.25})
                    CreateTween({Toggle, "BackgroundTransparency", 0.8, 0.25})
                    CreateTween({Toggle, "AnchorPoint", Vector2.new(0, 0.5), 0.25})
                end
            end
            SetToggle(Default)

            Button.Activated:Connect(function()
                SetToggle(not Default)
            end)

            local ToggleObj = {}
            function ToggleObj:Visible(...) Funcs:ToggleVisible(Button, ...) end
            function ToggleObj:Destroy() Button:Destroy() end
            function ToggleObj:Callback(...) Funcs:InsertCallback(Callback, ...) end
            function ToggleObj:Get() return Default end
            function ToggleObj:Set(Val1, Val2)
                if type(Val1) == "string" and type(Val2) == "string" then
                    LabelFunc:SetTitle(Val1)
                    LabelFunc:SetDesc(Val2)
                elseif type(Val1) == "string" then
                    LabelFunc:SetTitle(Val1)
                elseif type(Val1) == "boolean" then
                    SetToggle(Val1)
                elseif type(Val1) == "function" then
                    table.clear(Callback)
                    table.insert(Callback, Val1)
                end
            end
            return ToggleObj
        end

        function Tab:AddKeybind(Cfg)
            local KName = Cfg[1] or Cfg.Name or Cfg.Title or "Keybind"
            local KDefault = Cfg[2] or Cfg.Default or MyLibrary:GetToggleKey()
            local Callback = Funcs:GetCallback(Cfg, 3)

            if typeof(KDefault) == "EnumItem" then
                KDefault = KDefault.Name
            end

            local Button = InsertTheme(Create("Frame", Container, {
                Size = UDim2.new(1, 0, 0, 50),
                BackgroundColor3 = Theme["Color Hub 2"],
                Name = "Option"
            }), "Frame")
            AddTransparency(Button)
            Make("Corner", Button, UDim.new(0, 6))
            ApplyBorder(Button)

            InsertTheme(Create("TextLabel", Button, {
                Size = UDim2.new(1, -20, 0, 15),
                Position = UDim2.new(0, 10, 0, 5),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = KName,
                TextColor3 = Theme["Color Text"],
                TextSize = 9,
                TextXAlignment = "Left",
                TextTruncate = "AtEnd"
            }), "Text")

            local SelectedFrame = InsertTheme(Create("Frame", Button, {
                Size = UDim2.new(1, -20, 0, 22),
                Position = UDim2.new(0, 10, 0, 22),
                BackgroundColor3 = Theme["Color Stroke"]
            }), "Stroke")
            AddTransparency(SelectedFrame)
            Make("Corner", SelectedFrame, UDim.new(0, 4))

            local TextBoxInput = InsertTheme(Create("TextBox", SelectedFrame, {
                Size = UDim2.new(0.85, 0, 0.85, 0),
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.new(0.5, 0, 0.5, 0),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                TextScaled = true,
                TextColor3 = Theme["Color Text"],
                ClearTextOnFocus = false,
                PlaceholderText = "Pressione uma tecla...",
                Text = tostring(KDefault)
            }), "Text")

            local Keybind = {}
            local inputConnection = nil

            local function StopListening()
                if inputConnection then
                    inputConnection:Disconnect()
                    inputConnection = nil
                end
            end

            TextBoxInput.Focused:Connect(function()
                TextBoxInput.Text = "Pressione..."
                StopListening()

                inputConnection = UserInputService.InputBegan:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode ~= Enum.KeyCode.Unknown then
                        local keyPressed = input.KeyCode.Name
                        KDefault = keyPressed
                        TextBoxInput.Text = keyPressed
                        StopListening()
                        TextBoxInput:ReleaseFocus()
                        Funcs:FireCallback(Callback, keyPressed)
                    end
                end)
            end)

            TextBoxInput.FocusLost:Connect(function()
                StopListening()
                TextBoxInput.Text = tostring(KDefault)
            end)

            function Keybind:Visible(...) Funcs:ToggleVisible(Button, ...) end
            function Keybind:Destroy()
                StopListening()
                Button:Destroy()
            end
            function Keybind:Get() return KDefault end
            function Keybind:Set(NewKey)
                if typeof(NewKey) == "EnumItem" then NewKey = NewKey.Name end
                KDefault = tostring(NewKey)
                TextBoxInput.Text = KDefault
            end

            return Keybind
        end
    end

    ------------------------------------------------------------------
    -- COLOR PICKER (popup compartilhado)
    ------------------------------------------------------------------
    local function BuildColorPopup(PopupFolder, Title, StartColor, OnApply)
        local Blocker = Create("Frame", PopupFolder, {
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1,
            Visible = false,
            Active = true,
            ZIndex = 99,
            Name = "PopupBlocker_" .. Title
        })

        local Popup = Create("Frame", Blocker, {
            Size = UDim2.new(0, 230, 0, 230),
            Position = UDim2.new(0.5, -115, 0.5, -115),
            BackgroundColor3 = Color3.fromRGB(35, 35, 42),
            Active = true,
            ZIndex = 100,
            Name = "ColorPickerPopup"
        })
        Make("Corner", Popup, UDim.new(0, 8))
        Make("Stroke", Popup)
        Make("Gradient", Popup, { Rotation = 45 })

        local PopupTitle = InsertTheme(Create("TextLabel", Popup, {
            Size = UDim2.new(1, -16, 0, 22),
            Position = UDim2.new(0, 8, 0, 4),
            BackgroundTransparency = 1,
            Text = Title,
            TextColor3 = Color3.fromRGB(255, 255, 255),
            TextSize = 13,
            Font = Enum.Font.SourceSansBold,
            TextXAlignment = "Left",
            ZIndex = 101
        }), "Text")

        local PresetContainer = Create("Frame", Popup, {
            Size = UDim2.new(0, 70, 0, 120),
            Position = UDim2.new(0, 8, 0, 28),
            BackgroundTransparency = 1,
            ZIndex = 101
        })
        Create("UIGridLayout", PresetContainer, {
            CellSize = UDim2.new(0, 18, 0, 18),
            CellPadding = UDim2.new(0, 5, 0, 5)
        })

        local ColorMap = Create("Frame", Popup, {
            Size = UDim2.new(0, 130, 0, 120),
            Position = UDim2.new(0, 88, 0, 28),
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            ZIndex = 101,
            ClipsDescendants = true
        })
        Make("Corner", ColorMap, UDim.new(0, 4))

        Create("UIGradient", ColorMap, {
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 0, 0)),
                ColorSequenceKeypoint.new(0.166, Color3.fromRGB(255, 255, 0)),
                ColorSequenceKeypoint.new(0.333, Color3.fromRGB(0, 255, 0)),
                ColorSequenceKeypoint.new(0.5, Color3.fromRGB(0, 255, 255)),
                ColorSequenceKeypoint.new(0.666, Color3.fromRGB(0, 0, 255)),
                ColorSequenceKeypoint.new(0.833, Color3.fromRGB(255, 0, 255)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 0, 0))
            })
        })

        local SatOverlay = Create("Frame", ColorMap, {
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            ZIndex = 102
        })
        Make("Corner", SatOverlay, UDim.new(0, 4))
        Create("UIGradient", SatOverlay, {
            Rotation = 90,
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 1),
                NumberSequenceKeypoint.new(1, 0)
            })
        })

        local MapPointer = Create("Frame", ColorMap, {
            Size = UDim2.new(0, 8, 0, 8),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            BorderSizePixel = 1,
            BorderColor3 = Color3.fromRGB(0, 0, 0),
            ZIndex = 103
        })
        Make("Corner", MapPointer, UDim.new(1, 0))

        local ValueSlider = Create("Frame", Popup, {
            Size = UDim2.new(1, -16, 0, 14),
            Position = UDim2.new(0, 8, 0, 156),
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            ZIndex = 101
        })
        Make("Corner", ValueSlider, UDim.new(0, 4))
        local ValueGradient = Create("UIGradient", ValueSlider)

        local ValuePointer = Create("Frame", ValueSlider, {
            Size = UDim2.new(0, 8, 0, 18),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(1, 0, 0.5, 0),
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            BorderSizePixel = 1,
            BorderColor3 = Color3.fromRGB(0, 0, 0),
            ZIndex = 102
        })
        Make("Corner", ValuePointer, UDim.new(0, 3))

        -- Botoes sem tema (mantem a cor propria)
        local OkButton = Create("TextButton", Popup, {
            Size = UDim2.new(0.65, -12, 0, 28),
            Position = UDim2.new(0, 8, 1, -34),
            BackgroundColor3 = StartColor,
            AutoButtonColor = false,
            Text = "Aplicar Cor",
            TextColor3 = Color3.fromRGB(255, 255, 255),
            TextSize = 12,
            Font = Enum.Font.SourceSansBold,
            ZIndex = 101
        })
        Make("Corner", OkButton, UDim.new(0, 6))

        local CancelButton = Create("TextButton", Popup, {
            Size = UDim2.new(0.35, -8, 0, 28),
            Position = UDim2.new(0.65, 2, 1, -34),
            BackgroundColor3 = Color3.fromRGB(180, 50, 50),
            AutoButtonColor = false,
            Text = "Cancelar",
            TextColor3 = Color3.fromRGB(255, 255, 255),
            TextSize = 12,
            Font = Enum.Font.SourceSansBold,
            ZIndex = 101
        })
        Make("Corner", CancelButton, UDim.new(0, 6))

        local currentHue, currentSat, currentVal = 0, 1, 1
        local previewColor = StartColor
        local draggingMap, draggingSlider = false, false
        local inputMapConn, inputEndConn

        local function updatePickerVisuals()
            local pureColor = Color3.fromHSV(currentHue, currentSat, 1)
            ValueGradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 0, 0)),
                ColorSequenceKeypoint.new(1, pureColor)
            })
            previewColor = Color3.fromHSV(currentHue, currentSat, currentVal)
            OkButton.BackgroundColor3 = previewColor
            local brightness = (previewColor.R * 0.299) + (previewColor.G * 0.587) + (previewColor.B * 0.114)
            OkButton.TextColor3 = (brightness > 0.5) and Color3.fromRGB(20, 20, 20) or Color3.fromRGB(255, 255, 255)
        end

        local function updateMapInput(input)
            local absPos, absSize = ColorMap.AbsolutePosition, ColorMap.AbsoluteSize
            local mouseX = math.clamp(input.Position.X - absPos.X, 0, absSize.X)
            local mouseY = math.clamp(input.Position.Y - absPos.Y, 0, absSize.Y)
            currentHue = mouseX / absSize.X
            currentSat = 1 - (mouseY / absSize.Y)
            MapPointer.Position = UDim2.new(currentHue, 0, 1 - currentSat, 0)
            updatePickerVisuals()
        end

        local function updateSliderInput(input)
            local absPos, absSize = ValueSlider.AbsolutePosition, ValueSlider.AbsoluteSize
            local mouseX = math.clamp(input.Position.X - absPos.X, 0, absSize.X)
            currentVal = mouseX / absSize.X
            ValuePointer.Position = UDim2.new(currentVal, 0, 0.5, 0)
            updatePickerVisuals()
        end

        local function disconnectInputs()
            if inputMapConn then inputMapConn:Disconnect() inputMapConn = nil end
            if inputEndConn then inputEndConn:Disconnect() inputEndConn = nil end
            draggingMap = false
            draggingSlider = false
        end

        local function connectInputs()
            disconnectInputs()
            inputMapConn = Track(UserInputService.InputChanged:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                    if draggingMap then
                        updateMapInput(input)
                    elseif draggingSlider then
                        updateSliderInput(input)
                    end
                end
            end))

            inputEndConn = Track(UserInputService.InputEnded:Connect(function(input)
                if IsPress(input) then
                    draggingMap = false
                    draggingSlider = false
                end
            end))
        end

        ColorMap.InputBegan:Connect(function(input)
            if IsPress(input) then
                draggingMap = true
                updateMapInput(input)
            end
        end)

        ValueSlider.InputBegan:Connect(function(input)
            if IsPress(input) then
                draggingSlider = true
                updateSliderInput(input)
            end
        end)

        local presetColors = {
            Color3.fromRGB(255, 0, 0), Color3.fromRGB(0, 255, 0), Color3.fromRGB(0, 0, 255),
            Color3.fromRGB(255, 255, 0), Color3.fromRGB(0, 255, 255), Color3.fromRGB(255, 0, 255),
            Color3.fromRGB(255, 128, 0), Color3.fromRGB(128, 0, 255), Color3.fromRGB(0, 200, 100),
            Color3.fromRGB(255, 255, 255), Color3.fromRGB(120, 120, 120), Color3.fromRGB(0, 0, 0)
        }

        local function setFromColor(color)
            currentHue, currentSat, currentVal = color:ToHSV()
            MapPointer.Position = UDim2.new(currentHue, 0, 1 - currentSat, 0)
            ValuePointer.Position = UDim2.new(currentVal, 0, 0.5, 0)
            updatePickerVisuals()
        end

        for _, color in ipairs(presetColors) do
            local pBtn = Create("TextButton", PresetContainer, {
                BackgroundColor3 = color,
                Text = "",
                AutoButtonColor = false,
                ZIndex = 101
            })
            Make("Corner", pBtn, UDim.new(0, 3))
            pBtn.Activated:Connect(function()
                setFromColor(color)
            end)
        end

        local PopupObj = {}

        function PopupObj.Close()
            disconnectInputs()
            Blocker.Visible = false
        end

        function PopupObj.Open(color)
            setFromColor(color or previewColor)
            connectInputs()
            Blocker.Visible = true
        end

        function PopupObj.SetTitle(text)
            PopupTitle.Text = text
        end

        function PopupObj.Destroy()
            disconnectInputs()
            Blocker:Destroy()
        end

        OkButton.Activated:Connect(function()
            local picked = previewColor
            PopupObj.Close()
            OnApply(picked)
        end)
        CancelButton.Activated:Connect(PopupObj.Close)

        updatePickerVisuals()
        return PopupObj
    end

    local function BuildColorPicker(Container, Cfg, Ctx)
        local Stacked = Ctx.Stacked
        local CPName = Cfg[1] or Cfg.Name or Cfg.Title or "Color Picker"
        local CPDesc = Cfg.Desc or Cfg.Description or ""
        local CPCallback = Cfg.Callback or function() end
        local CPDefault = Cfg[2] or Cfg.Default or Color3.fromRGB(255, 255, 255)
        local CPFlag = Cfg.Flag or false

        if CheckFlag(CPFlag) then
            CPDefault = GetFlag(CPFlag) or CPDefault
        end
        if typeof(CPDefault) ~= "Color3" then
            CPDefault = Color3.fromRGB(255, 255, 255)
        end

        local Button, LabelFunc = ButtonFrame(Container, CPName, CPDesc, UDim2.new(1, Stacked and -115 or -125))

        local D = Stacked
            and {area = 105, right = -5, rgbW = 42, h = 14, btn = 16, btnX = 45, hexX = 64, hexW = 40, ts = 7}
            or {area = 115, right = -20, rgbW = 45, h = 16, btn = 18, btnX = 50, hexX = 73, hexW = 50, ts = 8}

        local RightArea = Create("Frame", Button, {
            Size = UDim2.new(0, D.area, 1),
            Position = UDim2.new(1, D.right, 0.5),
            AnchorPoint = Vector2.new(1, 0.5),
            BackgroundTransparency = 1
        })

        local RGBBox = Create("TextBox", RightArea, {
            Size = UDim2.new(0, D.rgbW, 0, D.h),
            Position = UDim2.new(0, 0, 0.5, -D.h / 2),
            BackgroundColor3 = Color3.fromRGB(20, 20, 25),
            Text = "",
            TextColor3 = Color3.fromRGB(220, 220, 230),
            TextSize = D.ts,
            Font = Enum.Font.GothamSemibold,
            ClearTextOnFocus = false,
            PlaceholderText = "R, G, B",
            PlaceholderColor3 = Color3.fromRGB(100, 100, 115)
        })
        Make("Corner", RGBBox, UDim.new(0, 3))

        local ColorButton = Create("ImageButton", RightArea, {
            Size = UDim2.new(0, D.btn, 0, D.btn),
            Position = UDim2.new(0, D.btnX, 0.5, -D.btn / 2),
            BackgroundColor3 = CPDefault,
            AutoButtonColor = false,
            Image = ""
        })
        Make("Corner", ColorButton, UDim.new(0, 3))

        local HexBox = Create("TextBox", RightArea, {
            Size = UDim2.new(0, D.hexW, 0, D.h),
            Position = UDim2.new(0, D.hexX, 0.5, -D.h / 2),
            BackgroundColor3 = Color3.fromRGB(20, 20, 25),
            Text = "",
            TextColor3 = CPDefault,
            TextSize = D.ts,
            Font = Enum.Font.GothamBold,
            ClearTextOnFocus = false,
            PlaceholderText = "#FFFFFF",
            PlaceholderColor3 = Color3.fromRGB(100, 100, 115)
        })
        Make("Corner", HexBox, UDim.new(0, 3))

        local isUpdating = false

        local function updateMainColor(newColor, skipCallback)
            if isUpdating then return end
            isUpdating = true

            ColorButton.BackgroundColor3 = newColor
            RGBBox.Text = math.round(newColor.R * 255) .. ", " .. math.round(newColor.G * 255) .. ", " .. math.round(newColor.B * 255)
            HexBox.Text = Color3ToHex(newColor)
            HexBox.TextColor3 = newColor
            if CPFlag then SetFlag(CPFlag, newColor) end

            if not skipCallback then
                task.spawn(CPCallback, newColor)
            end

            isUpdating = false
        end

        local Popup = BuildColorPopup(Ctx.PopupFolder, CPName, CPDefault, function(color)
            updateMainColor(color)
        end)

        ColorButton.Activated:Connect(function()
            Popup.Open(ColorButton.BackgroundColor3)
        end)

        RGBBox.FocusLost:Connect(function()
            local r, g, b = RGBBox.Text:match("(%d+)%s*,%s*(%d+)%s*,%s*(%d+)")
            if r and g and b then
                updateMainColor(Color3.fromRGB(
                    math.clamp(tonumber(r), 0, 255),
                    math.clamp(tonumber(g), 0, 255),
                    math.clamp(tonumber(b), 0, 255)
                ))
            else
                local cur = ColorButton.BackgroundColor3
                RGBBox.Text = math.round(cur.R * 255) .. ", " .. math.round(cur.G * 255) .. ", " .. math.round(cur.B * 255)
            end
        end)

        HexBox.FocusLost:Connect(function()
            local hexText = HexBox.Text:gsub("#", "")
            if #hexText == 6 and tonumber(hexText, 16) then
                local success, newColor = pcall(Color3.fromHex, hexText)
                if success then
                    updateMainColor(newColor)
                    return
                end
            end
            HexBox.Text = Color3ToHex(ColorButton.BackgroundColor3)
            HexBox.TextColor3 = ColorButton.BackgroundColor3
        end)

        updateMainColor(CPDefault, true)

        local ColorPicker = {}
        function ColorPicker:Set(color, skipCB) updateMainColor(color, skipCB) end
        function ColorPicker:Get() return ColorButton.BackgroundColor3 end
        function ColorPicker:Visible(...) Funcs:ToggleVisible(Button, ...) end
        function ColorPicker:Destroy() Popup.Destroy() Button:Destroy() end
        function ColorPicker:SetTitle(title) LabelFunc:SetTitle(title) Popup.SetTitle(title) end
        function ColorPicker:SetDesc(desc) LabelFunc:SetDesc(desc) end
        function ColorPicker:Callback(func) CPCallback = func end
        return ColorPicker
    end

    ------------------------------------------------------------------
    -- SLIDER (com botoes - e + nas laterais)
    ------------------------------------------------------------------
    local function BuildSlider(Container, Cfg, Stacked)
        local SName = Cfg[1] or Cfg.Name or Cfg.Title or "Slider!"
        local SDesc = Cfg.Desc or Cfg.Description or ""
        local MinV = Cfg[2] or Cfg.MinValue or Cfg.Min or 10
        local MaxV = Cfg[3] or Cfg.MaxValue or Cfg.Max or 100
        local Increase = Cfg[4] or Cfg.Increase or 1
        local Callback = Funcs:GetCallback(Cfg, 6)
        local Flag = Cfg[7] or Cfg.Flag or false
        local Default = Cfg[5] or Cfg.Default or 25
        if CheckFlag(Flag) then Default = GetFlag(Flag) end
        local Min, Max = MinV / Increase, MaxV / Increase

        local Button, LabelFunc, TitleLabel, SliderHolder, SliderBar, SetValueText
        local MinusBtn, PlusBtn

        -- Botao quadrado com o simbolo desenhado por barras (nao depende da fonte)
        local function MakeStepButton(Parent, Kind, Size, Position, Anchor)
            local Holder = InsertTheme(Create("Frame", Parent, {
                Size = Size,
                Position = Position,
                AnchorPoint = Anchor or Vector2.new(0, 0),
                BackgroundColor3 = Theme["Color Stroke"],
                Name = "Step" .. Kind
            }), "Stroke")
            AddTransparency(Holder)
            Make("Corner", Holder, UDim.new(0, 5))
            ApplyBorder(Holder)

            local function Bar(w, h)
                local b = InsertTheme(Create("Frame", Holder, {
                    Size = UDim2.fromOffset(w, h),
                    Position = UDim2.fromScale(0.5, 0.5),
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundColor3 = Theme["Color Text"],
                    BorderSizePixel = 0
                }), "Text")
                Make("Corner", b, UDim.new(1, 0))
                return b
            end

            Bar(10, 2)
            if Kind == "+" then Bar(2, 10) end

            local Click = Create("TextButton", Holder, {
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                Text = "",
                AutoButtonColor = false,
                ZIndex = 2
            })

            -- feedback ao apertar
            Click.MouseButton1Down:Connect(function()
                Holder.BackgroundTransparency = math.max(0.5, MyLibrary.Save.GlobalTransparency or 0)
            end)
            local function Release()
                Holder.BackgroundTransparency = MyLibrary.Save.GlobalTransparency or 0
            end
            Click.MouseButton1Up:Connect(Release)
            Click.MouseLeave:Connect(Release)

            return Click
        end

        if Stacked then
            Button = InsertTheme(Create("Frame", Container, {
                Size = UDim2.new(1, 0, 0, 52),
                BackgroundColor3 = Theme["Color Hub 2"],
                Name = "Option"
            }), "Frame")
            AddTransparency(Button)
            Make("Corner", Button, UDim.new(0, 6))
            ApplyBorder(Button)

            TitleLabel = InsertTheme(Create("TextLabel", Button, {
                Size = UDim2.new(1, -60, 0, 15),
                Position = UDim2.new(0, 10, 0, 5),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = SName,
                TextColor3 = Theme["Color Text"],
                TextSize = 9,
                TextXAlignment = "Left",
                TextTruncate = "AtEnd"
            }), "Text")

            local ValueLabel = InsertTheme(Create("TextLabel", Button, {
                Size = UDim2.new(0, 40, 0, 15),
                Position = UDim2.new(1, -10, 0, 5),
                AnchorPoint = Vector2.new(1, 0),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = tostring(Default),
                TextColor3 = Theme["Color Theme"],
                TextSize = 9,
                TextXAlignment = "Right"
            }), "Theme")
            SetValueText = function(text) ValueLabel.Text = text end

            MinusBtn = MakeStepButton(Button, "-",
                UDim2.new(0, 22, 0, 22),
                UDim2.new(0, 10, 0, 25))

            PlusBtn = MakeStepButton(Button, "+",
                UDim2.new(0, 22, 0, 22),
                UDim2.new(1, -10, 0, 25),
                Vector2.new(1, 0))

            SliderHolder = Create("TextButton", Button, {
                Size = UDim2.new(1, -80, 0, 26),
                Position = UDim2.new(0, 40, 0, 23),
                AutoButtonColor = false,
                Text = "",
                BackgroundTransparency = 1
            })

            SliderBar = InsertTheme(Create("Frame", SliderHolder, {
                BackgroundColor3 = Theme["Color Stroke"],
                Size = UDim2.new(1, -8, 0, 6),
                Position = UDim2.new(0.5, 0, 0.5),
                AnchorPoint = Vector2.new(0.5, 0.5)
            }), "Stroke")
        else
            Button, LabelFunc = ButtonFrame(Container, SName, SDesc, UDim2.new(1, -180))

            -- area que agrupa: [-] [slider] [+]
            local SliderArea = Create("Frame", Button, {
                Size = UDim2.new(0.45, 0, 1),
                Position = UDim2.new(1, -4, 0, 0),
                AnchorPoint = Vector2.new(1, 0),
                BackgroundTransparency = 1,
                Name = "SliderArea"
            })

            MinusBtn = MakeStepButton(SliderArea, "-",
                UDim2.new(0, 22, 0, 22),
                UDim2.new(0, 0, 0.5, 0),
                Vector2.new(0, 0.5))

            PlusBtn = MakeStepButton(SliderArea, "+",
                UDim2.new(0, 22, 0, 22),
                UDim2.new(1, 0, 0.5, 0),
                Vector2.new(1, 0.5))

            SliderHolder = Create("TextButton", SliderArea, {
                Size = UDim2.new(1, -56, 1, 0),
                Position = UDim2.new(0, 28, 0, 0),
                AutoButtonColor = false,
                Text = "",
                BackgroundTransparency = 1
            })

            SliderBar = InsertTheme(Create("Frame", SliderHolder, {
                BackgroundColor3 = Theme["Color Stroke"],
                Size = UDim2.new(1, -8, 0, 6),
                Position = UDim2.new(0.5, 0, 0.5),
                AnchorPoint = Vector2.new(0.5, 0.5)
            }), "Stroke")

            -- valor fica a esquerda do botao "-"
            local LabelVal = InsertTheme(Create("TextLabel", SliderArea, {
                Size = UDim2.new(0, 34, 0, 14),
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(0, -4, 0.5),
                BackgroundTransparency = 1,
                TextColor3 = Theme["Color Text"],
                Font = MyLibrary.CurrentFont,
                TextSize = 12,
                TextXAlignment = Enum.TextXAlignment.Right
            }), "Text")

            local UIScaleLocal = Create("UIScale", LabelVal)

            LabelVal:GetPropertyChangedSignal("Text"):Connect(function()
                UIScaleLocal.Scale = 0.3
                CreateTween({UIScaleLocal, "Scale", 1.2, 0.1})
                CreateTween({LabelVal, "Rotation", math.random(-1, 1) * 5, 0.15})
                task.delay(0.15, function()
                    CreateTween({UIScaleLocal, "Scale", 1, 0.2})
                    CreateTween({LabelVal, "Rotation", 0, 0.1})
                end)
            end)

            SetValueText = function(text) LabelVal.Text = text end
        end

        AddTransparency(SliderBar)
        Make("Corner", SliderBar)
        ApplyBorder(SliderBar)

        local Indicator = InsertTheme(Create("Frame", SliderBar, {
            BackgroundColor3 = Theme["Color Theme"],
            Size = UDim2.fromScale(0.3, 1),
            BorderSizePixel = 0
        }), "Theme")
        Make("Corner", Indicator)

        local SliderIcon = Create("Frame", SliderBar, {
            Size = UDim2.new(0, 8, 0, 14),
            BackgroundColor3 = Color3.fromRGB(220, 220, 220),
            Position = UDim2.fromScale(0.3, 0.5),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 0.2
        })
        Make("Corner", SliderIcon)

        local LastValue
        local Target = Default -- valor alvo (usado pelos botoes + e -)

        local function UpdateValues()
            Indicator.Size = UDim2.new(SliderIcon.Position.X.Scale, 0, 1, 0)
            local raw = math.floor(SliderIcon.Position.X.Scale * (Max - Min) + Min + 0.5)
            local Number = math.floor(raw * Increase * 10000 + 0.5) / 10000
            if Number == LastValue then return end
            LastValue = Number
            Default = Number
            SetValueText(tostring(Number))
            Funcs:FireCallback(Callback, Number)
        end

        local function SetSlider(NewValue, Instant)
            if type(NewValue) ~= "number" then return end
            NewValue = math.clamp(NewValue, MinV, MaxV)
            Target = NewValue
            local range = MaxV - MinV
            local pos = range ~= 0 and math.clamp((NewValue - MinV) / range, 0, 1) or 0
            SetFlag(Flag, NewValue)
            local target = UDim2.fromScale(pos, 0.5)
            if Instant then
                SliderIcon.Position = target
            else
                CreateTween({SliderIcon, "Position", target, 0.15})
            end
        end

        SliderIcon:GetPropertyChangedSignal("Position"):Connect(UpdateValues)
        BindSlider(SliderHolder, SliderBar, SliderIcon, Container, function()
            Target = Default
            SetFlag(Flag, Default)
        end)

        -- botoes + e - (clique e segurar para repetir)
        local function Step(Dir)
            SetSlider(math.floor((Target + Dir * Increase) * 10000 + 0.5) / 10000)
        end

        local function BindStep(Btn, Dir)
            local Holding = false
            Btn.MouseButton1Down:Connect(function()
                Holding = true
                Step(Dir)
                task.spawn(function()
                    task.wait(0.4)
                    while Holding do
                        Step(Dir)
                        task.wait(0.07)
                    end
                end)
            end)
            local function Stop() Holding = false end
            Btn.MouseButton1Up:Connect(Stop)
            Btn.MouseLeave:Connect(Stop)
        end

        BindStep(MinusBtn, -1)
        BindStep(PlusBtn, 1)

        SetSlider(Default, true)
        UpdateValues()

        local Slider = {}
        function Slider:Set(NewVal1, NewVal2)
            if type(NewVal1) == "number" then
                SetSlider(NewVal1)
            elseif type(NewVal1) == "function" then
                table.clear(Callback)
                table.insert(Callback, NewVal1)
            elseif type(NewVal1) == "string" then
                if LabelFunc then
                    LabelFunc:SetTitle(NewVal1)
                    if type(NewVal2) == "string" then LabelFunc:SetDesc(NewVal2) end
                else
                    TitleLabel.Text = NewVal1
                end
            end
        end
        function Slider:Get() return Default end
        function Slider:Callback(...) Funcs:InsertCallback(Callback, ...) end
        function Slider:Visible(...) Funcs:ToggleVisible(Button, ...) end
        function Slider:Destroy() Button:Destroy() end
        return Slider
    end

    ------------------------------------------------------------------
    -- TEXTBOX
    ------------------------------------------------------------------
    local function BuildTextBox(Container, Cfg, Stacked)
        local TName = Cfg[1] or Cfg.Name or Cfg.Title or "Text Box"
        local TDesc = Cfg.Desc or Cfg.Description or ""
        local TDefault = Cfg[2] or Cfg.Default or ""
        local TPlaceholderText = Cfg[5] or Cfg.PlaceholderText or "Input"
        local TClearText = Cfg[3] or Cfg.ClearText or Cfg.ClearTextOnFocus or false
        local Callback = Funcs:GetCallback(Cfg, 4)

        if type(TDefault) ~= "string" or TDefault:gsub(" ", ""):len() < 1 then
            TDefault = ""
        end

        local Button, SelectedFrame

        if Stacked then
            Button = InsertTheme(Create("Frame", Container, {
                Size = UDim2.new(1, 0, 0, 50),
                BackgroundColor3 = Theme["Color Hub 2"],
                Name = "Option"
            }), "Frame")
            AddTransparency(Button)
            Make("Corner", Button, UDim.new(0, 6))
            ApplyBorder(Button)

            InsertTheme(Create("TextLabel", Button, {
                Size = UDim2.new(1, -20, 0, 15),
                Position = UDim2.new(0, 10, 0, 5),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = TName,
                TextColor3 = Theme["Color Text"],
                TextSize = 9,
                TextXAlignment = "Left",
                TextTruncate = "AtEnd"
            }), "Text")

            SelectedFrame = InsertTheme(Create("Frame", Button, {
                Size = UDim2.new(1, -20, 0, 22),
                Position = UDim2.new(0, 10, 0, 22),
                BackgroundColor3 = Theme["Color Stroke"]
            }), "Stroke")
        else
            Button = ButtonFrame(Container, TName, TDesc, UDim2.new(1, -180))

            SelectedFrame = InsertTheme(Create("Frame", Button, {
                Size = UDim2.new(0, 150, 0, 18),
                Position = UDim2.new(1, -10, 0.5),
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundColor3 = Theme["Color Stroke"]
            }), "Stroke")
        end

        AddTransparency(SelectedFrame)
        Make("Corner", SelectedFrame, UDim.new(0, 4))

        local TextBoxInput = InsertTheme(Create("TextBox", SelectedFrame, {
            Size = UDim2.new(0.85, 0, 0.85, 0),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            BackgroundTransparency = 1,
            Font = MyLibrary.CurrentFont,
            TextScaled = true,
            TextColor3 = Theme["Color Text"],
            ClearTextOnFocus = TClearText,
            PlaceholderText = TPlaceholderText,
            Text = TDefault
        }), "Text")

        local Pencil
        if not Stacked then
            Pencil = Create("ImageLabel", SelectedFrame, {
                Size = UDim2.new(0, 12, 0, 12),
                Position = UDim2.new(0, -5, 0.5),
                AnchorPoint = Vector2.new(1, 0.5),
                Image = "rbxassetid://15637081879",
                BackgroundTransparency = 1
            })
            TextBoxInput.FocusLost:Connect(function()
                CreateTween({Pencil, "ImageColor3", Color3.fromRGB(255, 255, 255), 0.2})
            end)
            TextBoxInput.Focused:Connect(function()
                CreateTween({Pencil, "ImageColor3", Theme["Color Theme"], 0.2})
            end)
        end

        local TextBox = {}
        TextBox.OnChanging = false

        TextBoxInput.FocusLost:Connect(function()
            local Text = TextBoxInput.Text
            if Text:gsub(" ", ""):len() > 0 then
                if TextBox.OnChanging then Text = TextBox.OnChanging(Text) or Text end
                Funcs:FireCallback(Callback, Text)
                TextBoxInput.Text = Text
            end
        end)

        function TextBox:Visible(...) Funcs:ToggleVisible(Button, ...) end
        function TextBox:Destroy() Button:Destroy() end
        function TextBox:Get() return TextBoxInput.Text end
        function TextBox:Set(NewText)
            if type(NewText) == "string" then
                TextBoxInput.Text = NewText
            end
        end
        return TextBox
    end

    ------------------------------------------------------------------
    -- DROPDOWN (unico para as duas janelas)
    ------------------------------------------------------------------
    local function BuildDropdown(Container, Cfg, Ctx)
        local Stacked = Ctx.Stacked
        local DName = Cfg[1] or Cfg.Name or Cfg.Title or "Dropdown"
        local DDesc = Cfg.Desc or Cfg.Description or ""
        local DOptions = Cfg[2] or Cfg.Options or {}
        local OpDefault = Cfg[3] or Cfg.Default or {}
        local Flag = Cfg[5] or Cfg.Flag or false
        local MultiSelect = Cfg.MultiSelect or false
        local HasSearch = Cfg.Search or Cfg[6] or false
        local Callback = Funcs:GetCallback(Cfg, 4)

        local DropWidth = Ctx.DropWidth
        local OptionHeight = Stacked and 24 or 40
        local SearchHeight = 26
        local MaxVisible = Stacked and 8 or 7
        local SelH = OptionHeight - 14

        local Button, SelectedFrame, Opener

        if Stacked then
            Button = InsertTheme(Create("Frame", Container, {
                Size = UDim2.new(1, 0, 0, 50),
                BackgroundColor3 = Theme["Color Hub 2"],
                Name = "Option"
            }), "Frame")
            AddTransparency(Button)
            Make("Corner", Button, UDim.new(0, 6))
            ApplyBorder(Button)

            InsertTheme(Create("TextLabel", Button, {
                Size = UDim2.new(1, -20, 0, 15),
                Position = UDim2.new(0, 10, 0, 5),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = DName,
                TextColor3 = Theme["Color Text"],
                TextSize = 9,
                TextXAlignment = "Left",
                TextTruncate = "AtEnd"
            }), "Text")

            SelectedFrame = InsertTheme(Create("TextButton", Button, {
                Size = UDim2.new(1, -20, 0, 22),
                Position = UDim2.new(0, 10, 0, 22),
                BackgroundColor3 = Theme["Color Stroke"],
                AutoButtonColor = false,
                Text = ""
            }), "Stroke")
            Opener = SelectedFrame
        else
            Button = ButtonFrame(Container, DName, DDesc, UDim2.new(1, -180))

            SelectedFrame = InsertTheme(Create("Frame", Button, {
                Size = UDim2.new(0, 150, 0, 18),
                Position = UDim2.new(1, -10, 0.5),
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundColor3 = Theme["Color Stroke"]
            }), "Stroke")
            Opener = Button
        end

        AddTransparency(SelectedFrame)
        Make("Corner", SelectedFrame, UDim.new(0, 4))

        local ActiveLabel = InsertTheme(Create("TextLabel", SelectedFrame, {
            Size = UDim2.new(0.85, 0, 0.85, 0),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            BackgroundTransparency = 1,
            Font = MyLibrary.CurrentFont,
            TextScaled = true,
            TextColor3 = Theme["Color Text"],
            Text = "..."
        }), "Text")

        local DD_ARROW_DOWN, DD_ARROW_UP = "rbxassetid://10709791523", "rbxassetid://10709790948"
        local Arrow = Create("ImageLabel", SelectedFrame, {
            Size = UDim2.new(0, 15, 0, 15),
            Position = Stacked and UDim2.new(1, -5, 0.5) or UDim2.new(0, -5, 0.5),
            AnchorPoint = Vector2.new(1, 0.5),
            Image = DD_ARROW_DOWN,
            BackgroundTransparency = 1
        })

        local NoClickFrame = Create("TextButton", Ctx.DropHolder, {
            Name = "AntiClick",
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1,
            Visible = false,
            Text = ""
        })

        local DropFrame = Create("Frame", NoClickFrame, {
            Size = UDim2.new(0, DropWidth, 0, 0),
            BackgroundTransparency = 0.1,
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            AnchorPoint = Vector2.new(0, 0),
            Name = "DropdownFrame",
            ClipsDescendants = true,
            Active = true
        })
        Make("Corner", DropFrame)
        AddTransparency(DropFrame)
        Make("Stroke", DropFrame)
        Make("Gradient", DropFrame, { Rotation = 60 })

        local SearchTextBox
        if HasSearch then
            local SearchBox = Make("Button", DropFrame, {
                Name = "SearchBox",
                Size = UDim2.new(1, -16, 0, SearchHeight),
                Position = UDim2.new(0, 8, 0, 6),
                AnchorPoint = Vector2.new(0, 0)
            })
            Make("Corner", SearchBox, UDim.new(0, 4))

            SearchTextBox = InsertTheme(Create("TextBox", SearchBox, {
                Size = UDim2.new(1, -10, 1, 0),
                Position = UDim2.new(0, 8, 0, 0),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                TextSize = 12,
                TextColor3 = Theme["Color Text"],
                PlaceholderText = "Pesquisar...",
                PlaceholderColor3 = Theme["Color Dark Text"],
                Text = "",
                TextXAlignment = "Left"
            }), "Text")
        end

        local ScrollFrame = InsertTheme(Create("ScrollingFrame", DropFrame, {
            ScrollBarImageColor3 = Theme["Color Theme"],
            Size = HasSearch and UDim2.new(1, 0, 1, -(SearchHeight + 12)) or UDim2.new(1, 0, 1, 0),
            Position = HasSearch and UDim2.new(0, 0, 0, SearchHeight + 8) or UDim2.new(0, 0, 0, 0),
            ScrollBarThickness = 1.5,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            CanvasSize = UDim2.new(),
            ScrollingDirection = "Y",
            AutomaticCanvasSize = "Y",
            Active = true
        }, {
            Create("UIPadding", {
                PaddingLeft = UDim.new(0, 8),
                PaddingRight = UDim.new(0, 8),
                PaddingTop = UDim.new(0, HasSearch and 4 or 6),
                PaddingBottom = UDim.new(0, 6)
            }),
            Create("UIListLayout", { Padding = UDim.new(0, 4) })
        }), "ScrollBar")

        local ScrollSize, Busy, wasSearching = 5, false, false
        local Options = {}
        local Default = type(OpDefault) ~= "table" and {OpDefault} or OpDefault
        local Selected

        if MultiSelect then
            Selected = {}
            for index, Value in pairs(CheckFlag(Flag) and GetFlag(Flag) or Default) do
                if type(index) == "string" then
                    Selected[index] = Value == true
                elseif type(Value) == "string" then
                    Selected[Value] = true
                end
            end
        else
            Selected = CheckFlag(Flag) and GetFlag(Flag) or Default[1]
        end

        -- Declaradas antes para que os metodos publicos enxerguem
        local AddOption, RemoveOption, AddNewOptions, Select

        local function CallbackSelected()
            SetFlag(Flag, MultiSelect and Selected or tostring(Selected))
            Funcs:FireCallback(Callback, Selected)
        end

        local function UpdateLabel()
            if MultiSelect then
                local list = {}
                for index, Value in pairs(Selected) do
                    if Value then table.insert(list, index) end
                end
                table.sort(list)
                ActiveLabel.Text = #list > 0 and table.concat(list, ", ") or "..."
            else
                ActiveLabel.Text = tostring(Selected or "...")
            end
        end

        local function UpdateSelected()
            for _, v in pairs(Options) do
                local on
                if MultiSelect then on = v.Stats else on = (v.Value == Selected) end
                local nodes = v.nodes
                CreateTween({nodes[2], "BackgroundTransparency", on and 0 or 1, 0.35})
                CreateTween({nodes[2], "Size", on and UDim2.fromOffset(4, SelH) or UDim2.fromOffset(4, 4), 0.35})
                CreateTween({nodes[3], "TextTransparency", on and 0 or 0.4, 0.35})
            end
            UpdateLabel()
        end

        local function GetFrameSize()
            local Extra = HasSearch and (SearchHeight + 12) or 0
            return UDim2.fromOffset(DropWidth, ScrollSize + Extra)
        end

        -- A lista sempre fica colada no seletor (embaixo, ou em cima se nao couber)
        local function CalculatePos()
            DropFrame.AnchorPoint = Vector2.new(0, 0)
            DropFrame.Position = Ctx.Position(SelectedFrame, DropWidth, Cfg, GetFrameSize().Y.Offset)
        end

        local function CalculateSize(isSearching)
            if isSearching then return end
            local Count = 0
            for _, v in pairs(Options) do
                if v.nodes and v.nodes[1].Visible then Count = Count + 1 end
            end
            ScrollSize = math.clamp(Count, 0, MaxVisible) * (OptionHeight + 4) + 8
            if NoClickFrame.Visible then
                CalculatePos()
                CreateTween({DropFrame, "Size", GetFrameSize(), 0.2})
            end
        end

        local function ScrollToSelected()
            if MultiSelect or not Selected then return end
            for _, opt in pairs(Options) do
                if opt.Value == Selected and opt.nodes and opt.nodes[1] then
                    local btn = opt.nodes[1]
                    task.defer(function()
                        local yPos = btn.AbsolutePosition.Y - ScrollFrame.AbsolutePosition.Y + ScrollFrame.CanvasPosition.Y
                        ScrollFrame.CanvasPosition = Vector2.new(0, math.max(0, yPos - 5))
                    end)
                    break
                end
            end
        end

        Select = function(Option)
            if SearchTextBox and #SearchTextBox.Text > 0 then
                wasSearching = true
            end

            Option.LastCB = tick()
            if MultiSelect then
                Option.Stats = not Option.Stats
                Selected[Option.Name] = Option.Stats
            else
                Selected = Option.Value
            end
            CallbackSelected()
            UpdateSelected()
        end

        AddOption = function(index, Value)
            local Name = tostring(type(index) == "string" and index or Value)
            if Options[Name] then return end

            Options[Name] = {
                index = index,
                Value = Value,
                Name = Name,
                Stats = false,
                LastCB = 0
            }

            if MultiSelect then
                Options[Name].Stats = Selected[Name] == true
                Selected[Name] = Options[Name].Stats
            end

            local OptionButton = Make("Button", ScrollFrame, {
                Name = "Option",
                Size = UDim2.new(1, 0, 0, OptionHeight)
            })
            Make("Corner", OptionButton, UDim.new(0, 5))

            local IsSelected = InsertTheme(Create("Frame", OptionButton, {
                Position = UDim2.new(0, 2, 0.5),
                Size = UDim2.new(0, 4, 0, 4),
                BackgroundColor3 = Theme["Color Theme"],
                BackgroundTransparency = 1,
                AnchorPoint = Vector2.new(0, 0.5)
            }), "Theme")
            Make("Corner", IsSelected, UDim.new(0.5, 0))

            local OptionName = InsertTheme(Create("TextLabel", OptionButton, {
                Size = UDim2.new(1, -20, 1, 0),
                Position = UDim2.new(0, 14, 0.5),
                AnchorPoint = Vector2.new(0, 0.5),
                Text = Name,
                TextColor3 = Theme["Color Text"],
                Font = MyLibrary.CurrentFont,
                TextSize = Stacked and 10 or 13,
                TextXAlignment = "Left",
                BackgroundTransparency = 1,
                TextTransparency = 0.4,
                TextTruncate = "AtEnd"
            }), "Text")

            OptionButton.Activated:Connect(function()
                Select(Options[Name])
            end)
            Options[Name].nodes = {OptionButton, IsSelected, OptionName}
        end

        RemoveOption = function(index, Value)
            local Name = tostring(type(index) == "string" and index or Value)
            local opt = Options[Name]
            if opt then
                if MultiSelect then
                    Selected[Name] = nil
                elseif opt.Value == Selected then
                    Selected = nil
                end
                if opt.nodes and opt.nodes[1] then opt.nodes[1]:Destroy() end
                Options[Name] = nil
            end
        end

        AddNewOptions = function(List, Clear)
            local previous = Selected
            if Clear then
                local names = {}
                for k, v in pairs(Options) do table.insert(names, {k, v.Value}) end
                for _, pair in ipairs(names) do RemoveOption(pair[1], pair[2]) end
            end
            for k, v in pairs(List) do AddOption(k, v) end

            -- mantem a selecao se a opcao ainda existe
            if not MultiSelect and previous ~= nil and Selected == nil then
                for _, opt in pairs(Options) do
                    if opt.Value == previous then Selected = previous end
                end
            end

            CalculateSize(false)
            CallbackSelected()
            UpdateSelected()
        end

        if SearchTextBox then
            SearchTextBox:GetPropertyChangedSignal("Text"):Connect(function()
                local query = string.lower(SearchTextBox.Text)
                for _, item in pairs(Options) do
                    item.nodes[1].Visible = query == "" or string.find(string.lower(item.Name), query, 1, true) ~= nil
                end
                CalculateSize(true)
            end)
        end

        for k, v in pairs(DOptions) do AddOption(k, v) end
        CallbackSelected()
        UpdateSelected()

        local function Close()
            if Busy or not NoClickFrame.Visible then return end
            Busy = true
            Arrow.Image = DD_ARROW_DOWN
            CreateTween({Arrow, "ImageColor3", Color3.fromRGB(255, 255, 255), 0.2})
            CreateTween({DropFrame, "Size", UDim2.new(0, DropWidth, 0, 0), 0.2, true})
            NoClickFrame.Visible = false
            Busy = false
        end

        local function ForceClose()
            NoClickFrame.Visible = false
            DropFrame.Size = UDim2.new(0, DropWidth, 0, 0)
            Arrow.Image = DD_ARROW_DOWN
            Arrow.ImageColor3 = Color3.fromRGB(255, 255, 255)
        end

        local function Open()
            if Busy then return end
            if SearchTextBox then
                SearchTextBox.Text = ""
                for _, item in pairs(Options) do item.nodes[1].Visible = true end
            end
            NoClickFrame.Visible = true
            Arrow.Image = DD_ARROW_UP
            CreateTween({Arrow, "ImageColor3", Theme["Color Theme"], 0.2})
            CalculateSize(false)
            CalculatePos()
            CreateTween({DropFrame, "Size", GetFrameSize(), 0.2})

            if wasSearching then
                ScrollToSelected()
                wasSearching = false
            end
        end

        Opener.Activated:Connect(function()
            if NoClickFrame.Visible then Close() else Open() end
        end)
        NoClickFrame.MouseButton1Down:Connect(Close)
        Ctx.VisibleFrame:GetPropertyChangedSignal("Visible"):Connect(ForceClose)
        SelectedFrame:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
            if NoClickFrame.Visible then CalculatePos() end
        end)
        ScrollFrame.ChildAdded:Connect(function() CalculateSize(false) end)
        ScrollFrame.ChildRemoved:Connect(function() CalculateSize(false) end)
        CalculatePos()

        local Dropdown = {}
        function Dropdown:Visible(...) Funcs:ToggleVisible(Button, ...) end
        function Dropdown:Destroy() NoClickFrame:Destroy() Button:Destroy() end
        function Dropdown:Callback(...) Funcs:InsertCallback(Callback, ...) end
        function Dropdown:Get() return Selected end

        function Dropdown:Add(...)
            local NewOptions = {...}
            if type(NewOptions[1]) == "table" then NewOptions = NewOptions[1] end
            for _, Name in ipairs(NewOptions) do AddOption(Name, Name) end
            CalculateSize(false)
        end

        function Dropdown:Remove(Option)
            local found = {}
            for index, Value in pairs(Options) do
                if (type(Option) == "number" and Value.index == Option) or Value.Name == Option then
                    table.insert(found, {Value.index, Value.Value})
                end
            end
            for _, pair in ipairs(found) do RemoveOption(pair[1], pair[2]) end
            UpdateSelected()
            CalculateSize(false)
        end

        function Dropdown:Select(Option)
            for _, Val in pairs(Options) do
                if (type(Option) == "string" and Val.Name == Option) or (type(Option) == "number" and Val.index == Option) then
                    Select(Val)
                    break
                end
            end
        end

        -- Set(tabela, manterAntigas): por padrao substitui as opcoes
        function Dropdown:Set(Val1, Keep)
            if type(Val1) == "table" then
                AddNewOptions(Val1, not Keep)
            elseif type(Val1) == "function" then
                table.clear(Callback)
                table.insert(Callback, Val1)
            elseif type(Val1) == "string" then
                Dropdown:Select(Val1)
            end
        end
        function Dropdown:SetOptions(list) AddNewOptions(list, true) end
        function Dropdown:Refresh(list) AddNewOptions(list, true) end

        return Dropdown
    end

    ------------------------------------------------------------------
    -- CONTEXTOS (janela principal x janela secundaria)
    ------------------------------------------------------------------
    local RowCtx = {
        Stacked = false,
        PopupFolder = Create("Folder", MainFrame, { Name = "ColorPickerPopups" }),
        DropHolder = DropdownHolder,
        DropWidth = 180,
        VisibleFrame = MainFrame,
        -- posiciona a lista logo abaixo do seletor (ou acima se nao couber na tela)
        Position = function(Sel, W, Cfg, H)
            H = H or 0
            local scale = UIScale
            local screenW = ScreenGui.AbsoluteSize.X / scale
            local screenH = ScreenGui.AbsoluteSize.Y / scale

            local selX = Sel.AbsolutePosition.X / scale
            local selY = Sel.AbsolutePosition.Y / scale
            local selW = Sel.AbsoluteSize.X / scale
            local selH = Sel.AbsoluteSize.Y / scale

            local x = math.clamp(selX + selW - W, 4, math.max(4, screenW - W - 4))
            local y = selY + selH + 4
            if y + H > screenH - 4 then
                y = math.max(4, selY - H - 4)
            end
            return UDim2.fromOffset(x, y)
        end
    }

    local StackedCtx = {
        Stacked = true,
        PopupFolder = Create("Folder", SecondaryFrame, { Name = "ColorPickerPopups" }),
        DropHolder = SecondaryDropdownHolder,
        DropWidth = 210,
        VisibleFrame = SecondaryFrame,
        Position = function(Sel, W, Cfg, H)
            H = H or 0
            local scale = UIScale
            local selX = (Sel.AbsolutePosition.X - SecondaryFrame.AbsolutePosition.X) / scale
            local selY = (Sel.AbsolutePosition.Y - SecondaryFrame.AbsolutePosition.Y) / scale
            local selW = Sel.AbsoluteSize.X / scale
            local selH = Sel.AbsoluteSize.Y / scale
            local frameW = SecondaryFrame.AbsoluteSize.X / scale
            local frameH = SecondaryFrame.AbsoluteSize.Y / scale

            local x = math.clamp(selX + selW - W, 0, math.max(0, frameW - W))
            local y = selY + selH + 2
            if y + H > frameH then
                y = math.max(0, selY - H - 2)
            end
            return UDim2.fromOffset(x, y)
        end
    }

    AttachElements = function(Tab, Container, Ctx)
        AttachCommon(Tab, Container, Ctx)
        function Tab:AddSlider(Cfg) return BuildSlider(Container, Cfg, Ctx.Stacked) end
        function Tab:AddTextBox(Cfg) return BuildTextBox(Container, Cfg, Ctx.Stacked) end
        function Tab:AddColorPicker(Cfg) return BuildColorPicker(Container, Cfg, Ctx) end
        function Tab:AddDropdown(Cfg) return BuildDropdown(Container, Cfg, Ctx) end
        if Ctx == RowCtx and AttachExtras then
            AttachExtras(Tab, Container)
        end
    end

    ------------------------------------------------------------------
    -- EXTRAS DA JANELA PRINCIPAL (dropdown de players e convite)
    -- Funcionam tanto direto na aba quanto dentro de uma secao.
    ------------------------------------------------------------------
    AttachExtras = function(Tab, Container)
        ------------------------------------------------------------------
        -- DROPDOWN DE PLAYERS
        ------------------------------------------------------------------
        function Tab:AddDropdownPlayer(Cfg2)
            local DName = Cfg2[1] or Cfg2.Name or Cfg2.Title or "..."
            local DDesc = Cfg2.Desc or Cfg2.Description or ""
            local OpDefault = Cfg2[3] or Cfg2.Default or "..."
            local Flag = Cfg2[5] or Cfg2.Flag or false
            local Callback = Funcs:GetCallback(Cfg2, 4)

            local autoSelectEnabled = Cfg2.AutoSelect
            if autoSelectEnabled == nil then autoSelectEnabled = true end

            local clickToSelectEnabled = Cfg2.ClickToSelect
            if clickToSelectEnabled == nil then clickToSelectEnabled = Cfg2.ClickPlayer end
            if clickToSelectEnabled == nil then clickToSelectEnabled = true end

            local CustomOptions = Cfg2.Options or Cfg2[2]
            local LocalPlayer = Players.LocalPlayer

            local wasSearching = false
            local hasAutoSelected = false
            local suppressInitialNotify = true

            local DROPDOWN_WIDTH = RowCtx.DropWidth
            local OPTION_HEIGHT = 40
            local SEARCH_HEIGHT = 26
            local MAX_VISIBLE_OPTS = 7

            local Button = ButtonFrame(Container, DName, DDesc, UDim2.new(1, -180))
            -- linha mais alta para caber o mini toggle "Click Player" dentro da propria linha
            Button.Size = UDim2.new(1, 0, 0, clickToSelectEnabled and 46 or 25)

            local SelectedFrame = InsertTheme(Create("Frame", Button, {
                Size = UDim2.new(0, 150, 0, 22),
                Position = clickToSelectEnabled and UDim2.new(1, -10, 0, 5) or UDim2.new(1, -10, 0.5),
                AnchorPoint = clickToSelectEnabled and Vector2.new(1, 0) or Vector2.new(1, 0.5),
                BackgroundColor3 = Theme["Color Stroke"]
            }), "Stroke")
            AddTransparency(SelectedFrame)
            Make("Corner", SelectedFrame, UDim.new(0, 4))

            local SelectedPlayerIcon = Create("ImageLabel", SelectedFrame, {
                Size = UDim2.fromOffset(20, 20),
                Position = UDim2.new(0, 2, 0.5),
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundTransparency = 1,
                Image = "",
                Visible = false
            })
            Make("Corner", SelectedPlayerIcon, UDim.new(0.5, 0))

            local ActiveLabel = InsertTheme(Create("TextLabel", SelectedFrame, {
                Size = UDim2.new(1, -25, 0.85, 0),
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.new(0.5, -8, 0.5, 0),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                TextScaled = true,
                TextColor3 = Theme["Color Text"],
                Text = tostring(OpDefault),
                TextXAlignment = "Center"
            }), "Text")

            local PL_ARROW_DOWN, PL_ARROW_UP = "rbxassetid://10709791523", "rbxassetid://10709790948"
            local Arrow = Create("ImageLabel", SelectedFrame, {
                Size = UDim2.new(0, 15, 0, 15),
                Position = UDim2.new(1, -5, 0.5),
                AnchorPoint = Vector2.new(1, 0.5),
                Image = PL_ARROW_DOWN,
                BackgroundTransparency = 1
            })

            -- mini toggle "Click Player"
            local ClickToggleActive = false

            local ClickPlayerFrame = Create("TextButton", Button, {
                Size = UDim2.new(0, 150, 0, 14),
                Position = UDim2.new(1, -10, 0, 29),
                AnchorPoint = Vector2.new(1, 0),
                BackgroundTransparency = 1,
                Text = "",
                Visible = clickToSelectEnabled
            })

            InsertTheme(Create("TextLabel", ClickPlayerFrame, {
                Size = UDim2.new(1, -30, 1, 0),
                Position = UDim2.new(0, 0, 0.5, 0),
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                TextSize = 10,
                TextColor3 = Theme["Color Dark Text"],
                Text = "Click Player",
                TextXAlignment = "Right"
            }), "SubText")

            local MiniToggleHolder = InsertTheme(Create("Frame", ClickPlayerFrame, {
                Size = UDim2.new(0, 26, 0, 13),
                Position = UDim2.new(1, 0, 0.5, 0),
                AnchorPoint = Vector2.new(1, 0.5),
                BackgroundColor3 = Theme["Color Stroke"]
            }), "Stroke")
            AddTransparency(MiniToggleHolder)
            Make("Corner", MiniToggleHolder, UDim.new(0.5, 0))

            local MiniSlider = Create("Frame", MiniToggleHolder, {
                BackgroundTransparency = 1,
                Size = UDim2.new(0.8, 0, 0.8, 0),
                Position = UDim2.new(0.5, 0, 0.5, 0),
                AnchorPoint = Vector2.new(0.5, 0.5)
            })

            local MiniToggle = InsertTheme(Create("Frame", MiniSlider, {
                Size = UDim2.new(0, 9, 0, 9),
                Position = UDim2.new(0, 0, 0.5),
                AnchorPoint = Vector2.new(0, 0.5),
                BackgroundColor3 = Theme["Color Theme"],
                BackgroundTransparency = 0.8
            }), "Theme")
            Make("Corner", MiniToggle, UDim.new(0.5, 0))

            local function UpdateToggleUI(val)
                if val then
                    CreateTween({MiniToggle, "Position", UDim2.new(1, 0, 0.5), 0.25})
                    CreateTween({MiniToggle, "BackgroundTransparency", 0, 0.25})
                    CreateTween({MiniToggle, "AnchorPoint", Vector2.new(1, 0.5), 0.25})
                else
                    CreateTween({MiniToggle, "Position", UDim2.new(0, 0, 0.5), 0.25})
                    CreateTween({MiniToggle, "BackgroundTransparency", 0.8, 0.25})
                    CreateTween({MiniToggle, "AnchorPoint", Vector2.new(0, 0.5), 0.25})
                end
            end

            ClickPlayerFrame.Activated:Connect(function()
                ClickToggleActive = not ClickToggleActive
                UpdateToggleUI(ClickToggleActive)
            end)

            local NoClickFrame = Create("TextButton", DropdownHolder, {
                Name = "AntiClick",
                Size = UDim2.new(1, 0, 1, 0),
                BackgroundTransparency = 1,
                Visible = false,
                Text = ""
            })

            local DropFrame = Create("Frame", NoClickFrame, {
                Size = UDim2.new(0, DROPDOWN_WIDTH, 0, 0),
                BackgroundTransparency = 0.1,
                BackgroundColor3 = Color3.fromRGB(255, 255, 255),
                AnchorPoint = Vector2.new(0, 0),
                Name = "DropdownFrame",
                ClipsDescendants = true,
                Active = true
            })
            Make("Corner", DropFrame)
            AddTransparency(DropFrame)
            Make("Stroke", DropFrame)
            Make("Gradient", DropFrame, { Rotation = 60 })

            local SearchBox = Make("Button", DropFrame, {
                Name = "SearchBox",
                Size = UDim2.new(1, -16, 0, SEARCH_HEIGHT),
                Position = UDim2.new(0, 8, 0, 6),
                AnchorPoint = Vector2.new(0, 0)
            })
            Make("Corner", SearchBox, UDim.new(0, 4))

            local SearchTextBox = InsertTheme(Create("TextBox", SearchBox, {
                Size = UDim2.new(1, -10, 1, 0),
                Position = UDim2.new(0, 8, 0, 0),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                TextSize = 12,
                TextColor3 = Theme["Color Text"],
                PlaceholderText = "Pesquisar...",
                PlaceholderColor3 = Theme["Color Dark Text"],
                Text = "",
                TextXAlignment = "Left"
            }), "Text")

            local ScrollFrame = InsertTheme(Create("ScrollingFrame", DropFrame, {
                ScrollBarImageColor3 = Theme["Color Theme"],
                Size = UDim2.new(1, 0, 1, -(SEARCH_HEIGHT + 12)),
                Position = UDim2.new(0, 0, 0, SEARCH_HEIGHT + 8),
                ScrollBarThickness = 1.5,
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                CanvasSize = UDim2.new(),
                ScrollingDirection = "Y",
                AutomaticCanvasSize = "Y",
                Active = true
            }, {
                Create("UIPadding", {
                    PaddingLeft = UDim.new(0, 8),
                    PaddingRight = UDim.new(0, 8),
                    PaddingTop = UDim.new(0, 4),
                    PaddingBottom = UDim.new(0, 6)
                }),
                Create("UIListLayout", { Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder })
            }), "ScrollBar")

            local ScrollSize, Busy = 5, false
            local Options = {}
            local Selected = CheckFlag(Flag) and GetFlag(Flag) or OpDefault

            local function GetFrameSize()
                return UDim2.fromOffset(DROPDOWN_WIDTH, ScrollSize + SEARCH_HEIGHT + 14)
            end

            -- a lista sempre fica colada no seletor (embaixo, ou em cima se nao couber)
            local function CalculatePos()
                DropFrame.AnchorPoint = Vector2.new(0, 0)
                DropFrame.Position = RowCtx.Position(SelectedFrame, DROPDOWN_WIDTH, Cfg2, GetFrameSize().Y.Offset)
            end

            local function CalculateSize(isSearching)
                if isSearching then return end
                local Count = 0
                for _, v in pairs(Options) do
                    if v.nodes[1] and v.nodes[1].Visible then Count = Count + 1 end
                end
                ScrollSize = math.clamp(Count, 0, MAX_VISIBLE_OPTS) * (OPTION_HEIGHT + 4) + 8
                if NoClickFrame.Visible then
                    CalculatePos()
                    CreateTween({DropFrame, "Size", GetFrameSize(), 0.2})
                end
            end

            local function SendPlayerNotification(plr, titleMessage)
                if not plr then return end
                task.spawn(function()
                    local thumb = ""
                    pcall(function()
                        local content, isReady = Players:GetUserThumbnailAsync(
                            plr.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
                        if isReady then thumb = content end
                    end)

                    MyLibrary:NotifyWithImage({
                        Title = titleMessage,
                        SubTitle = plr.DisplayName,
                        Message = "@" .. plr.Name,
                        Image = thumb,
                        Duration = 4
                    })
                end)
            end

            local function UpdateHeaderAvatar(playerObj)
                if playerObj then
                    task.spawn(function()
                        pcall(function()
                            local content, isReady = Players:GetUserThumbnailAsync(
                                playerObj.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
                            if isReady then
                                SelectedPlayerIcon.Image = content
                                SelectedPlayerIcon.Visible = true
                                ActiveLabel.AnchorPoint = Vector2.new(0, 0.5)
                                ActiveLabel.Position = UDim2.new(0, 26, 0.5, 0)
                                ActiveLabel.Size = UDim2.new(1, -45, 0.85, 0)
                                ActiveLabel.TextXAlignment = Enum.TextXAlignment.Left
                            end
                        end)
                    end)
                else
                    SelectedPlayerIcon.Visible = false
                    ActiveLabel.AnchorPoint = Vector2.new(0.5, 0.5)
                    ActiveLabel.Position = UDim2.new(0.5, -8, 0.5, 0)
                    ActiveLabel.Size = UDim2.new(1, -25, 0.85, 0)
                    ActiveLabel.TextXAlignment = Enum.TextXAlignment.Center
                end
            end

            local function CallbackSelected()
                SetFlag(Flag, tostring(Selected))
                Funcs:FireCallback(Callback, Selected)
            end

            local function UpdateLabel()
                local plr = Players:FindFirstChild(tostring(Selected))
                if plr then
                    ActiveLabel.Text = plr.DisplayName
                    UpdateHeaderAvatar(plr)
                else
                    ActiveLabel.Text = tostring(Selected or "...")
                    UpdateHeaderAvatar(nil)
                end
            end

            local function UpdateSelected()
                for _, v in pairs(Options) do
                    local Slt = v.Value == Selected
                    local nodes = v.nodes
                    if nodes[2] then
                        CreateTween({nodes[2], "BackgroundTransparency", Slt and 0 or 1, 0.35})
                        CreateTween({nodes[2], "Size", Slt and UDim2.fromOffset(4, 26) or UDim2.fromOffset(4, 4), 0.35})
                        CreateTween({nodes[3], "TextTransparency", Slt and 0 or 0.2, 0.35})
                        CreateTween({nodes[4], "TextTransparency", Slt and 0.2 or 0.5, 0.35})
                    end
                end
                UpdateLabel()
            end

            local function ScrollToSelected()
                if not Selected or Selected == "..." then return end
                for _, opt in pairs(Options) do
                    if opt.Value == Selected and opt.nodes[1] then
                        local btn = opt.nodes[1]
                        task.defer(function()
                            local yPos = btn.AbsolutePosition.Y - ScrollFrame.AbsolutePosition.Y + ScrollFrame.CanvasPosition.Y
                            ScrollFrame.CanvasPosition = Vector2.new(0, math.max(0, yPos - 5))
                        end)
                        break
                    end
                end
            end

            local function Select(Option)
                if #SearchTextBox.Text > 0 then wasSearching = true end

                Option.LastCB = tick()
                Selected = Option.Value
                CallbackSelected()
                UpdateSelected()

                if not suppressInitialNotify then
                    local plr = Players:FindFirstChild(Selected)
                    if plr then SendPlayerNotification(plr, "Player Selecionado:") end
                end
            end

            local function AddOption(plr)
                local Name = plr.Name
                if Options[Name] then return end

                local isFriend = false
                pcall(function()
                    isFriend = LocalPlayer:IsFriendsWith(plr.UserId)
                end)

                local displayName = plr.DisplayName
                if isFriend then displayName = displayName .. " -AMG" end

                Options[Name] = {
                    Value = Name,
                    Name = Name,
                    DisplayName = displayName,
                    IsFriend = isFriend,
                    nodes = {}
                }

                local OptButton = Make("Button", ScrollFrame, {
                    Name = "Option",
                    Size = UDim2.new(1, 0, 0, OPTION_HEIGHT),
                    LayoutOrder = isFriend and 1 or 2
                })
                Make("Corner", OptButton, UDim.new(0, 5))

                local IsSelected = InsertTheme(Create("Frame", OptButton, {
                    Position = UDim2.new(0, 2, 0.5),
                    Size = UDim2.new(0, 4, 0, 4),
                    BackgroundColor3 = Theme["Color Theme"],
                    BackgroundTransparency = 1,
                    AnchorPoint = Vector2.new(0, 0.5)
                }), "Theme")
                Make("Corner", IsSelected, UDim.new(0.5, 0))

                local PlayerIcon = Create("ImageLabel", OptButton, {
                    Size = UDim2.fromOffset(30, 30),
                    Position = UDim2.new(0, 10, 0.5),
                    AnchorPoint = Vector2.new(0, 0.5),
                    BackgroundTransparency = 1,
                    Image = ""
                })
                Make("Corner", PlayerIcon, UDim.new(0.5, 0))

                task.spawn(function()
                    pcall(function()
                        local content, isReady = Players:GetUserThumbnailAsync(
                            plr.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
                        if isReady then PlayerIcon.Image = content end
                    end)
                end)

                local DisplayLabel = InsertTheme(Create("TextLabel", OptButton, {
                    Size = UDim2.new(1, -54, 0, 16),
                    Position = UDim2.new(0, 46, 0, 5),
                    Text = displayName,
                    TextColor3 = Theme["Color Text"],
                    Font = MyLibrary.CurrentFont,
                    TextSize = 13,
                    TextXAlignment = "Left",
                    BackgroundTransparency = 1,
                    TextTransparency = 0.2,
                    TextTruncate = "AtEnd"
                }), "Text")

                local UserLabel = InsertTheme(Create("TextLabel", OptButton, {
                    Size = UDim2.new(1, -54, 0, 12),
                    Position = UDim2.new(0, 46, 0, 22),
                    Text = "@" .. Name,
                    TextColor3 = Theme["Color Dark Text"],
                    Font = MyLibrary.CurrentFont,
                    TextSize = 11,
                    TextXAlignment = "Left",
                    BackgroundTransparency = 1,
                    TextTransparency = 0.5,
                    TextTruncate = "AtEnd"
                }), "SubText")

                OptButton.Activated:Connect(function()
                    if Options[Name] then Select(Options[Name]) end
                end)

                Options[Name].nodes = {OptButton, IsSelected, DisplayLabel, UserLabel}
            end

            local function RemoveOption(Name)
                local opt = Options[Name]
                if opt then
                    if opt.nodes[1] then opt.nodes[1]:Destroy() end
                    Options[Name] = nil
                end
            end

            local function RefreshPlayers()
                if CustomOptions and type(CustomOptions) == "table" then
                    local toRemove = {}
                    for name in pairs(Options) do
                        if not table.find(CustomOptions, name) then table.insert(toRemove, name) end
                    end
                    for _, name in ipairs(toRemove) do RemoveOption(name) end

                    for _, name in ipairs(CustomOptions) do
                        local plr = Players:FindFirstChild(name)
                        if plr and plr ~= LocalPlayer then AddOption(plr) end
                    end
                else
                    local toRemove = {}
                    for name in pairs(Options) do
                        if not Players:FindFirstChild(name) then table.insert(toRemove, name) end
                    end
                    for _, name in ipairs(toRemove) do RemoveOption(name) end

                    for _, plr in ipairs(Players:GetPlayers()) do
                        if plr ~= LocalPlayer then AddOption(plr) end
                    end
                end

                if not hasAutoSelected then
                    hasAutoSelected = true

                    if autoSelectEnabled then
                        local firstOption, firstFriend = nil, nil
                        for _, opt in pairs(Options) do
                            if opt.IsFriend and not firstFriend then
                                firstFriend = opt
                            elseif not firstOption then
                                firstOption = opt
                            end
                        end

                        local autoTarget = firstFriend or firstOption
                        if autoTarget then
                            Selected = autoTarget.Value
                            CallbackSelected()
                        else
                            Selected = "..."
                        end
                    else
                        Selected = OpDefault
                    end
                elseif Selected and Selected ~= "..." then
                    if not Options[Selected] or not Players:FindFirstChild(Selected) then
                        Selected = "..."
                        CallbackSelected()
                    end
                end

                UpdateSelected()
                CalculateSize(false)
            end

            -- clique no personagem para selecionar
            local cClick = Track(UserInputService.InputBegan:Connect(function(input, gameProcessed)
                if gameProcessed or not clickToSelectEnabled or not ClickToggleActive then return end

                if IsPress(input) then
                    local target = LocalPlayer:GetMouse().Target
                    if target then
                        local characterModel = target:FindFirstAncestorOfClass("Model")
                        if characterModel then
                            local playerFound = Players:GetPlayerFromCharacter(characterModel)
                            if playerFound and playerFound ~= LocalPlayer then
                                if Options[playerFound.Name] then
                                    Select(Options[playerFound.Name])
                                else
                                    Selected = playerFound.Name
                                    CallbackSelected()
                                    UpdateSelected()
                                    SendPlayerNotification(playerFound, "Player Selecionado:")
                                end
                            end
                        end
                    end
                end
            end))

            SearchTextBox:GetPropertyChangedSignal("Text"):Connect(function()
                local query = string.lower(SearchTextBox.Text)
                for _, item in pairs(Options) do
                    local matchDisplay = string.find(string.lower(item.DisplayName), query, 1, true)
                    local matchUser = string.find(string.lower(item.Name), query, 1, true)
                    item.nodes[1].Visible = query == "" or matchDisplay ~= nil or matchUser ~= nil
                end
                CalculateSize(true)
            end)

            local function Close()
                if Busy or not NoClickFrame.Visible then return end
                Busy = true
                Arrow.Image = PL_ARROW_DOWN
                CreateTween({Arrow, "ImageColor3", Color3.fromRGB(255, 255, 255), 0.2})
                CreateTween({DropFrame, "Size", UDim2.new(0, DROPDOWN_WIDTH, 0, 0), 0.2, true})
                NoClickFrame.Visible = false
                Busy = false
            end

            local function ForceClose()
                NoClickFrame.Visible = false
                DropFrame.Size = UDim2.new(0, DROPDOWN_WIDTH, 0, 0)
                Arrow.Image = PL_ARROW_DOWN
                Arrow.ImageColor3 = Color3.fromRGB(255, 255, 255)
            end

            local function Open()
                if Busy then return end
                SearchTextBox.Text = ""
                for _, item in pairs(Options) do item.nodes[1].Visible = true end
                NoClickFrame.Visible = true
                Arrow.Image = PL_ARROW_UP
                CreateTween({Arrow, "ImageColor3", Theme["Color Theme"], 0.2})
                CalculateSize(false)
                CalculatePos()
                CreateTween({DropFrame, "Size", GetFrameSize(), 0.2})

                if wasSearching then
                    ScrollToSelected()
                    wasSearching = false
                end
            end

            Button.Activated:Connect(function()
                if NoClickFrame.Visible then Close() else Open() end
            end)
            NoClickFrame.MouseButton1Down:Connect(Close)
            MainFrame:GetPropertyChangedSignal("Visible"):Connect(ForceClose)
            SelectedFrame:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
                if NoClickFrame.Visible then CalculatePos() end
            end)
            ScrollFrame.ChildAdded:Connect(function() CalculateSize(false) end)
            ScrollFrame.ChildRemoved:Connect(function() CalculateSize(false) end)

            local c1 = Players.PlayerAdded:Connect(function()
                task.wait(0.3)
                RefreshPlayers()
            end)

            local c2 = Players.PlayerRemoving:Connect(function(plr)
                RemoveOption(plr.Name)
                if Selected == plr.Name then
                    SendPlayerNotification(plr, "O Player Selecionado Saiu:")
                    Selected = "..."
                    CallbackSelected()
                end
                RefreshPlayers()
            end)
            Track(c1)
            Track(c2)

            RefreshPlayers()
            CalculatePos()
            suppressInitialNotify = false

            local Dropdown = {}
            Dropdown.ActiveLabel = ActiveLabel
            function Dropdown:Visible(...) Funcs:ToggleVisible(Button, ...) end
            function Dropdown:Destroy()
                c1:Disconnect()
                c2:Disconnect()
                cClick:Disconnect()
                NoClickFrame:Destroy()
                Button:Destroy()
            end
            function Dropdown:Get() return Selected end
            function Dropdown:Set(Val1)
                if type(Val1) == "string" then
                    Selected = Val1
                    UpdateSelected()
                end
            end
            function Dropdown:Refresh(newOptions)
                if type(newOptions) == "table" then
                    CustomOptions = newOptions
                end
                RefreshPlayers()
            end

            return Dropdown
        end

        ------------------------------------------------------------------
        -- CONVITE (TikTok / Discord)
        ------------------------------------------------------------------
        function Tab:AddDiscordInvite(Cfg2)
            local ITitle = Cfg2.Name or Cfg2.Title or Cfg2[1] or "Minhas Redes"
            local Desc = Cfg2.Description or Cfg2.Desc or ""
            local Logo = Cfg2.Logo or Cfg2[2] or ""
            local TikTokLink = Cfg2["Tik Tok"] or Cfg2.TikTok or Cfg2.TikTokInvite or ""
            local DiscordLink = Cfg2.Discord or Cfg2.Invite or Cfg2[3] or ""

            local InviteHolder = Create("Frame", Container, {
                Size = UDim2.new(1, 0, 0, 130),
                Name = "Option",
                BackgroundTransparency = 1
            })
            Make("Corner", InviteHolder, UDim.new(0, 6))
            ApplyBorder(InviteHolder)

            local FrameHolder = InsertTheme(Create("Frame", InviteHolder, {
                Size = UDim2.new(1, 0, 1, 0),
                BackgroundColor3 = Theme["Color Hub 2"],
                ClipsDescendants = true
            }), "Frame")
            AddTransparency(FrameHolder)
            Make("Corner", FrameHolder, UDim.new(0, 6))

            local ImageLabel = Create("ImageLabel", FrameHolder, {
                Size = UDim2.new(1, 0, 0, 85),
                Image = "",
                BackgroundTransparency = 1,
                ScaleType = Enum.ScaleType.Crop
            })
            Make("Corner", ImageLabel, UDim.new(0, 6))

            if Logo ~= "" then
                task.spawn(function()
                    if Logo:find("https://") or Logo:find("http://") then
                        if requestFunc and getAssetFunc and writefile then
                            -- nome de arquivo fixo por link (evita acumular arquivos)
                            local hash = #Logo
                            for i = 1, #Logo do hash = (hash * 31 + Logo:byte(i)) % 1000000007 end
                            local fileName = IMAGES_FOLDER .. "/Invite_" .. hash .. ".png"

                            if not (isfile and isfile(fileName)) then
                                local ok, resp = pcall(requestFunc, {
                                    Url = Logo,
                                    Method = "GET",
                                    Headers = {["User-Agent"] = "Mozilla/5.0"}
                                })
                                if ok and resp and resp.Body then
                                    pcall(writefile, fileName, resp.Body)
                                end
                            end

                            if isfile and isfile(fileName) then
                                ImageLabel.Image = getAssetFunc(fileName)
                            end
                        end
                    else
                        local formatted = Logo
                        if not Logo:find("rbxassetid://") and not Logo:find("rbxasset://") then
                            formatted = "rbxassetid://" .. Logo
                        end
                        ImageLabel.Image = formatted
                    end
                end)
            end

            local BottomBar = InsertTheme(Create("Frame", FrameHolder, {
                Size = UDim2.new(1, 0, 0, 48),
                AnchorPoint = Vector2.new(0, 1),
                Position = UDim2.new(0, 0, 1, 0),
                BackgroundColor3 = Theme["Color Hub 2"]
            }), "Frame")
            Make("Corner", BottomBar, UDim.new(0, 6))
            AddTransparency(BottomBar)

            InsertTheme(Create("TextLabel", BottomBar, {
                Size = UDim2.new(1, -210, 0, 16),
                Position = UDim2.new(0, 10, 0, 6),
                Font = MyLibrary.CurrentFont,
                TextColor3 = Theme["Color Text"],
                TextXAlignment = "Left",
                BackgroundTransparency = 1,
                TextSize = 11,
                Text = ITitle
            }), "Text")

            InsertTheme(Create("TextLabel", BottomBar, {
                Size = UDim2.new(1, -210, 0, 18),
                Position = UDim2.new(0, 10, 0, 24),
                Font = MyLibrary.CurrentFont,
                TextColor3 = Theme["Color Dark Text"],
                TextXAlignment = "Left",
                BackgroundTransparency = 1,
                TextSize = 9,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Text = Desc
            }), "DarkText")

            local ButtonContainer = Create("Frame", BottomBar, {
                Size = UDim2.new(0, 190, 0, 32),
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                BackgroundTransparency = 1
            })

            Create("UIListLayout", ButtonContainer, {
                FillDirection = Enum.FillDirection.Horizontal,
                HorizontalAlignment = Enum.HorizontalAlignment.Right,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 6)
            })

            local function MakeLinkButton(Label, Color, IconId, Link)
                local Btn = Create("TextButton", ButtonContainer, {
                    Size = UDim2.new(0, 90, 0, 28),
                    Text = "  " .. Label,
                    Font = MyLibrary.CurrentFont,
                    TextSize = 10,
                    TextColor3 = Color3.fromRGB(255, 255, 255),
                    BackgroundColor3 = Color
                })
                Make("Corner", Btn, UDim.new(0, 6))

                Create("ImageLabel", Btn, {
                    Size = UDim2.new(0, 14, 0, 14),
                    AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, 6, 0.5, 0),
                    Image = IconId,
                    BackgroundTransparency = 1
                })

                local Delay = false
                Btn.Activated:Connect(function()
                    local copy = setclipboard or toclipboard
                    if Link ~= "" and copy then
                        pcall(copy, Link)
                    end
                    if Delay then return end
                    Delay = true
                    Btn.Text = "Copiado!"
                    task.wait(2)
                    Btn.Text = "  " .. Label
                    Delay = false
                end)
            end

            MakeLinkButton("TikTok", Color3.fromRGB(10, 10, 10), "rbxassetid://140658929749855", TikTokLink)
            MakeLinkButton("Discord", Color3.fromRGB(88, 101, 242), "rbxassetid://7552532178", DiscordLink)

            local DiscordInvite = {}
            function DiscordInvite:Destroy() InviteHolder:Destroy() end
            function DiscordInvite:Visible(...) Funcs:ToggleVisible(InviteHolder, ...) end
            return DiscordInvite
        end
    end

