    local ThemeSync = {}

    local function SyncPicker(picker, getter)
        table.insert(ThemeSync, function() picker:Set(getter(), true) end)
        return picker
    end

    local function SyncSlider(slider, getter)
        table.insert(ThemeSync, function() slider:Set(getter()) end)
        return slider
    end

    local function RefreshThemeControls()
        for _, fn in ipairs(ThemeSync) do pcall(fn) end
    end

