    local EFFECTS_FILE = LibFolder .. "/ExtrasConfig.json"

    local EffectsConfig = {
        RGBEnabled = false,
        CustomColorEnabled = false,
        SelectedEffect = "Onda (Wave)",
        CustomColor = nil,
        Speed = 1
    }

    local function SaveEffectsSettings()
        local data = {
            RGBEnabled = EffectsConfig.RGBEnabled,
            CustomColorEnabled = EffectsConfig.CustomColorEnabled,
            SelectedEffect = EffectsConfig.SelectedEffect,
            Speed = EffectsConfig.Speed,
            CustomColorHex = EffectsConfig.CustomColor and Color3ToHex(EffectsConfig.CustomColor) or nil
        }
        SaveJson(EFFECTS_FILE, data)
    end

    local function GetDefaultLibColor()
        return HexToColor(MyLibrary:GetStrokeColor() or "#8A2BE2")
    end

    local function LoadEffectsSettings()
        if isfile and readfile and isfile(EFFECTS_FILE) then
            local success, result = pcall(function()
                return HttpService:JSONDecode(readfile(EFFECTS_FILE))
            end)

            if success and type(result) == "table" then
                if result.RGBEnabled ~= nil then EffectsConfig.RGBEnabled = result.RGBEnabled == true end
                if result.CustomColorEnabled ~= nil then EffectsConfig.CustomColorEnabled = result.CustomColorEnabled == true end
                if type(result.SelectedEffect) == "string" then EffectsConfig.SelectedEffect = result.SelectedEffect end
                if tonumber(result.Speed) then EffectsConfig.Speed = tonumber(result.Speed) end
                if type(result.CustomColorHex) == "string" then
                    EffectsConfig.CustomColor = HexToColor3(result.CustomColorHex)
                end
            end
        end

        if not EffectsConfig.CustomColor then
            EffectsConfig.CustomColor = GetDefaultLibColor()
        end

        if EffectsConfig.RGBEnabled and EffectsConfig.CustomColorEnabled then
            EffectsConfig.CustomColorEnabled = false
        end
    end

    LoadEffectsSettings()

    local function RestoreOriginalColor()
        pcall(function()
            MyLibrary:SetStrokeColor(GetDefaultLibColor())
        end)
    end

    local function StopRenderLoop()
        if Env.SAGAZ_EffectsConnection then
            Env.SAGAZ_EffectsConnection:Disconnect()
            Env.SAGAZ_EffectsConnection = nil
        end
    end

    ScreenGui.Destroying:Connect(StopRenderLoop)

    local cachedBorders, lastBorderRefresh = {}, 0
    local function GetLibBorders()
        if tick() - lastBorderRefresh > 1 then
            lastBorderRefresh = tick()
            cachedBorders = {}
            for _, descendant in ipairs(MainFrame:GetDescendants()) do
                if descendant.Name == "LibBorder" then
                    table.insert(cachedBorders, descendant)
                end
            end
        end
        return cachedBorders
    end

    local function UpdateEffects()
        StopRenderLoop()

        if not EffectsConfig.RGBEnabled and not EffectsConfig.CustomColorEnabled then
            RestoreOriginalColor()
            return
        end

        lastBorderRefresh = 0

        Env.SAGAZ_EffectsConnection = RunService.RenderStepped:Connect(function()
            if not EffectsConfig.RGBEnabled and not EffectsConfig.CustomColorEnabled then
                StopRenderLoop()
                RestoreOriginalColor()
                return
            end

            local time = tick() * EffectsConfig.Speed
            local borders = GetLibBorders()
            local baseTransparency = MyLibrary.Save.StrokeTransparency or 0
            local effectType = EffectsConfig.SelectedEffect
            local custom = EffectsConfig.CustomColor
            local baseHue, baseSat, baseVal = custom:ToHSV()
            local rgb = EffectsConfig.RGBEnabled

            for index, border in ipairs(borders) do
                if border.Parent then
                    local color = Color3.new(1, 1, 1)
                    local transparency = baseTransparency

                    if effectType == "Onda (Wave)" then
                        local wave = math.sin((time * 3) + (index * 0.5)) * 0.5 + 0.5
                        if rgb then
                            color = Color3.fromHSV(((time * 0.2) + (index * 0.08)) % 1, 0.85, 1)
                        else
                            color = Color3.fromHSV(baseHue, baseSat, baseVal * (0.3 + (wave * 0.7)))
                        end

                    elseif effectType == "Pulso (Pulse)" then
                        local pulse = (math.sin(time * 4) + 1) / 2
                        if rgb then
                            color = Color3.fromHSV((time * 0.15) % 1, 0.8, 0.4 + (pulse * 0.6))
                        else
                            color = Color3.fromHSV(baseHue, baseSat, baseVal * (0.3 + (pulse * 0.7)))
                        end

                    elseif effectType == "Respiracao (Breathing)" then
                        local alpha = (math.sin(time * 2.5) + 1) / 2
                        transparency = baseTransparency + (1 - baseTransparency) * (1 - alpha)
                        color = rgb and Color3.fromHSV((time * 0.1) % 1, 0.85, 1) or custom

                    elseif effectType == "Pisca-Pisca (Strobe)" then
                        if (math.floor(time * 6) % 2) == 0 then
                            color = rgb and Color3.fromHSV((time * 0.3) % 1, 1, 1) or custom
                        else
                            transparency = 1
                            color = custom
                        end

                    elseif effectType == "Brilho Alternado (Ping-Pong)" then
                        local pingPong = math.abs(math.sin(time * 2 + (index * 0.3)))
                        if rgb then
                            color = Color3.fromHSV((time * 0.2 + (index * 0.1)) % 1, 0.85, pingPong)
                        else
                            color = Color3.fromHSV(baseHue, baseSat * pingPong, baseVal)
                        end
                    end

                    if border:IsA("UIStroke") then
                        border.Color = color
                        border.Transparency = transparency
                    end
                end
            end
        end)
    end

    ExtrasTab:AddSection({"Efeitos de Borda"})

    local ToggleRGBObj, ToggleCustomColorObj

    ExtrasTab:AddDropdown({
        Name = "Efeito da Borda",
        Options = {
