    ToggleRGBObj = ExtrasTab:AddToggle({
        Name = "Ativar Efeito RGB",
        Default = EffectsConfig.RGBEnabled,
        Callback = function(state)
            if EffectsConfig.RGBEnabled == state and EffectsConfig._init then return end
            EffectsConfig.RGBEnabled = state

            if state then
                EffectsConfig.CustomColorEnabled = false
                if ToggleCustomColorObj then ToggleCustomColorObj:Set(false) end
            end

            SaveEffectsSettings()
            UpdateEffects()
        end
    })

    ToggleCustomColorObj = ExtrasTab:AddToggle({
        Name = "Ativar Cor Personalizada",
        Default = EffectsConfig.CustomColorEnabled,
        Callback = function(state)
            if EffectsConfig.CustomColorEnabled == state and EffectsConfig._init then return end
            EffectsConfig.CustomColorEnabled = state

            if state then
                EffectsConfig.RGBEnabled = false
                if ToggleRGBObj then ToggleRGBObj:Set(false) end
            end

            SaveEffectsSettings()
            UpdateEffects()
        end
    })

    EffectsConfig._init = true

    task.defer(function()
        task.wait(0.3)
        if EffectsConfig.RGBEnabled or EffectsConfig.CustomColorEnabled then
            UpdateEffects()
        else
            StopRenderLoop()
            RestoreOriginalColor()
        end
    end)

