    ------------------------------------------------------------------
    -- DIALOG (janela de confirmacao)
    ------------------------------------------------------------------
    function Window:Dialog(Cfg)
        if MainFrame:FindFirstChild("Dialog") then return end
        if Minimized then Window:MinimizeBtn() end

        local DTitle = Cfg[1] or Cfg.Title or "Dialog"
        local DText = Cfg[2] or Cfg.Text or "This is a Dialog"
        local DOptions = Cfg[3] or Cfg.Options or {}

        -- fundo escurecido por cima do hub
        local Screen = Create("Frame", MainFrame, {
            Name = "Dialog",
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundColor3 = Color3.fromRGB(0, 0, 0),
            BackgroundTransparency = 1,
            Active = true,
            ZIndex = 50
        })
        MainCorner:Clone().Parent = Screen

        -- cartao centralizado (ajusta a altura sozinho)
        local Card = InsertTheme(Create("Frame", Screen, {
            Size = UDim2.new(0, 270, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            Position = UDim2.fromScale(0.5, 0.5),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = Theme["Color Hub 2"],
            BorderSizePixel = 0
        }, {
            Create("UIListLayout", {
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 8)
            }),
            Create("UIPadding", {
                PaddingLeft = UDim.new(0, 14),
                PaddingRight = UDim.new(0, 14),
                PaddingTop = UDim.new(0, 12),
                PaddingBottom = UDim.new(0, 14)
            }),
            Create("UIScale", { Scale = 0.92, Name = "DialogScale" })
        }), "Frame")
        Make("Corner", Card, UDim.new(0, 8))
        ApplyBorder(Card)

        InsertTheme(Create("TextLabel", Card, {
            Size = UDim2.new(1, 0, 0, 20),
            BackgroundTransparency = 1,
            Font = MyLibrary.CurrentFont,
            Text = DTitle,
            TextColor3 = Theme["Color Text"],
            TextSize = 16,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            LayoutOrder = 1
        }), "Text")

        InsertTheme(Create("Frame", Card, {
            Size = UDim2.new(1, 0, 0, 2),
            BackgroundColor3 = Theme["Color Theme"],
            BorderSizePixel = 0,
            LayoutOrder = 2
        }), "Theme")

        InsertTheme(Create("TextLabel", Card, {
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            Font = MyLibrary.CurrentFont,
            Text = DText,
            TextColor3 = Theme["Color Dark Text"],
            TextSize = 12,
            TextWrapped = true,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top,
            LayoutOrder = 3
        }), "DarkText")

        local ButtonsHolder = Create("Frame", Card, {
            Size = UDim2.new(1, 0, 0, 32),
            BackgroundTransparency = 1,
            LayoutOrder = 4
        }, {
            Create("UIListLayout", {
                FillDirection = Enum.FillDirection.Horizontal,
                SortOrder = Enum.SortOrder.LayoutOrder,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                Padding = UDim.new(0, 8)
            })
        })

        local DialogScale = Card:FindFirstChild("DialogScale")
        CreateTween({Screen, "BackgroundTransparency", 0.45, 0.2})
        CreateTween({DialogScale, "Scale", 1, 0.2})

        local Dialog, Closing, Buttons = {}, false, {}

        function Dialog:Close()
            if Closing then return end
            Closing = true
            CreateTween({Screen, "BackgroundTransparency", 1, 0.15})
            CreateTween({DialogScale, "Scale", 0.92, 0.15, true})
            Screen:Destroy()
        end

        function Dialog:Button(BCfg)
            local Name = BCfg[1] or BCfg.Name or BCfg.Title or ""
            local Callback = BCfg[2] or BCfg.Callback or function() end

            local Holder = InsertTheme(Create("Frame", ButtonsHolder, {
                BackgroundColor3 = Theme["Color Stroke"],
                BorderSizePixel = 0,
                LayoutOrder = #Buttons + 1
            }), "Stroke")
            AddTransparency(Holder)
            Make("Corner", Holder, UDim.new(0, 6))
            ApplyBorder(Holder)

            local Btn = InsertTheme(Create("TextButton", Holder, {
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                AutoButtonColor = false,
                Text = Name,
                Font = MyLibrary.CurrentFont,
                TextColor3 = Theme["Color Text"],
                TextSize = 12
            }), "Text")

            Btn.MouseEnter:Connect(function()
                Holder.BackgroundTransparency = math.max(0.4, MyLibrary.Save.GlobalTransparency or 0)
            end)
            Btn.MouseLeave:Connect(function()
                Holder.BackgroundTransparency = MyLibrary.Save.GlobalTransparency or 0
            end)

            table.insert(Buttons, Holder)
            local count = #Buttons
            for _, b in ipairs(Buttons) do
                b.Size = UDim2.new(1 / count, -((count - 1) * 8) / count, 1, 0)
            end

            Btn.Activated:Connect(function() Dialog:Close() end)
            Btn.Activated:Connect(Callback)
        end

        for _, Button in ipairs(DOptions) do
            Dialog:Button(Button)
        end
        return Dialog
    end

    ------------------------------------------------------------------
    -- JANELA DE UPDATE
    -- So aparece uma vez por conteudo: se o texto da update mudar,
    -- ela aparece de novo. Window:ShowUpdate(cfg, true) forca mostrar.
    ------------------------------------------------------------------
    local UPDATE_GREEN = Color3.fromRGB(88, 210, 125)
    local UPDATE_RED = Color3.fromRGB(245, 90, 90)
    local UPDATE_YELLOW = Color3.fromRGB(245, 200, 70)

    function Window:ShowUpdate(Cfg, Force)
        Cfg = Cfg or UpdateCfg
        if type(Cfg) ~= "table" then return false end

        local uTitle = tostring(Cfg.Title or Cfg.Name or Cfg[1] or "Atualizacao")
        local uGame = tostring(Cfg.Game or Cfg.SubTitle or Cfg[2] or "")
        local uLog = Cfg.Log or Cfg.Changes or Cfg[3] or ""
        if type(uLog) == "table" then uLog = table.concat(uLog, "\n") end
        uLog = tostring(uLog)

        local key = tostring(Cfg.Id or (uGame ~= "" and uGame) or "default")
        local hash = SimpleHash(uTitle .. "\n" .. uGame .. "\n" .. uLog)

        local seen = MyLibrary.Save.SeenUpdates
        if type(seen) ~= "table" then
            seen = {}
            MyLibrary.Save.SeenUpdates = seen
        end
        if not Force and seen[key] == hash then return false end
        if ScreenGui:FindFirstChild("UpdateWindow") then return false end

        seen[key] = hash
        SaveLib()

        local Overlay = Create("Frame", ScreenGui, {
            Name = "UpdateWindow",
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = Color3.fromRGB(0, 0, 0),
            BackgroundTransparency = 1,
            Active = true,
            ZIndex = 2000
        })

        local Card = InsertTheme(Create("Frame", Overlay, {
            Size = UDim2.fromOffset(290, 220),
            Position = UDim2.fromScale(0.5, 0.5),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = Theme["Color Hub 2"],
            BorderSizePixel = 0,
            ClipsDescendants = true,
            ZIndex = 2001
        }, {
            Create("UIScale", { Scale = 0.9, Name = "UpdateScale" })
        }), "Frame")
        Make("Corner", Card, UDim.new(0, 8))
        ApplyBorder(Card)

        InsertTheme(Create("TextLabel", Card, {
            Size = UDim2.new(1, -44, 0, 22),
            Position = UDim2.new(0, 14, 0, 8),
            BackgroundTransparency = 1,
            Font = MyLibrary.CurrentFont,
            Text = uTitle,
            TextColor3 = Theme["Color Text"],
            TextSize = 16,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = 2002
        }), "Text")

        if uGame ~= "" then
            InsertTheme(Create("TextLabel", Card, {
                Size = UDim2.new(1, -44, 0, 16),
                Position = UDim2.new(0, 14, 0, 30),
                BackgroundTransparency = 1,
                Font = MyLibrary.CurrentFont,
                Text = uGame,
                TextColor3 = Theme["Color Dark Text"],
                TextSize = 12,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                ZIndex = 2002
            }), "DarkText")
        end

        local CloseX = InsertTheme(Create("TextButton", Card, {
            Size = UDim2.new(0, 26, 0, 26),
            Position = UDim2.new(1, -6, 0, 6),
            AnchorPoint = Vector2.new(1, 0),
            BackgroundTransparency = 1,
            Text = "X",
            Font = Enum.Font.GothamBold,
            TextSize = 13,
            TextColor3 = Theme["Color Dark Text"],
            AutoButtonColor = false,
            ZIndex = 2003
        }), "DarkText")

        -- bloco de codigo (estilo diff do Discord)
        local CodeBlock = Create("Frame", Card, {
            Size = UDim2.new(1, -28, 1, -96),
            Position = UDim2.new(0, 14, 0, 52),
            BackgroundColor3 = Color3.fromRGB(24, 25, 28),
            BorderSizePixel = 0,
            ZIndex = 2002
        })
        Make("Corner", CodeBlock, UDim.new(0, 6))
        ApplyBorder(CodeBlock)

        local CodeScroll = InsertTheme(Create("ScrollingFrame", CodeBlock, {
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ScrollBarThickness = 2,
            ScrollBarImageColor3 = Theme["Color Theme"],
            CanvasSize = UDim2.new(),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollingDirection = Enum.ScrollingDirection.Y,
            ZIndex = 2003
        }, {
            Create("UIPadding", {
                PaddingLeft = UDim.new(0, 10),
                PaddingRight = UDim.new(0, 10),
                PaddingTop = UDim.new(0, 8),
                PaddingBottom = UDim.new(0, 8)
            }),
            Create("UIListLayout", {
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 3)
            })
        }), "ScrollBar")

        local order = 0
        for rawLine in uLog:gmatch("[^\r\n]+") do
            local line = rawLine:match("^%s*(.-)%s*$")
            -- ignora as cercas de markdown (```diff e ```)
            if line ~= "" and line:sub(1, 3) ~= "```" then
                local first = line:sub(1, 1)
                local color = Color3.fromRGB(210, 212, 218)
                if first == "+" then
                    color = UPDATE_GREEN
                elseif first == "-" then
                    color = UPDATE_RED
                elseif first == "!" then
                    color = UPDATE_YELLOW
                end

                order = order + 1
                Create("TextLabel", CodeScroll, {
                    Size = UDim2.new(1, 0, 0, 0),
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    Font = Enum.Font.Code,
                    Text = line,
                    TextColor3 = color,
                    TextSize = 11,
                    TextWrapped = true,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextYAlignment = Enum.TextYAlignment.Top,
                    LayoutOrder = order,
                    ZIndex = 2004
                })
            end
        end

        -- botao "Entendi"
        local OkHolder = InsertTheme(Create("Frame", Card, {
            Size = UDim2.new(1, -28, 0, 28),
            Position = UDim2.new(0, 14, 1, -36),
            BackgroundColor3 = Theme["Color Theme"],
            BorderSizePixel = 0,
            ZIndex = 2002
        }), "Theme")
        Make("Corner", OkHolder, UDim.new(0, 6))

        local OkButton = Create("TextButton", OkHolder, {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            AutoButtonColor = false,
            Text = "Entendi",
            Font = MyLibrary.CurrentFont,
            TextColor3 = Color3.fromRGB(255, 255, 255),
            TextSize = 13,
            ZIndex = 2003
        })

        local UpdateScale = Card:FindFirstChild("UpdateScale")
        CreateTween({Overlay, "BackgroundTransparency", 0.5, 0.25})
        CreateTween({UpdateScale, "Scale", 1, 0.25})

        local closing = false
        local function CloseUpdate()
            if closing then return end
            closing = true
            CreateTween({Overlay, "BackgroundTransparency", 1, 0.15})
            CreateTween({UpdateScale, "Scale", 0.9, 0.15, true})
            Overlay:Destroy()
        end
        OkButton.Activated:Connect(CloseUpdate)
        CloseX.Activated:Connect(CloseUpdate)

        return true
    end

    function Window:SelectTab(TabSelect)
        if type(TabSelect) == "number" then
            local entry = MyLibrary.Tabs[TabSelect]
            if entry then entry.func:Enable() end
        else
            for _, Tab in ipairs(MyLibrary.Tabs) do
                if Tab.Cont == TabSelect.Cont then
                    Tab.func:Enable()
                end
            end
        end
    end

    ------------------------------------------------------------------
    -- ABAS DA JANELA PRINCIPAL
    ------------------------------------------------------------------
    local ContainerList = {}

    function Window:MakeTab(paste, Cfg)
        if type(paste) == "table" then Cfg = paste end
        local TName = Cfg[1] or Cfg.Title or "Tab!"
        local TIcon = MyLibrary:GetIcon(Cfg[2] or Cfg.Icon or "")

        if type(TIcon) ~= "string" or not TIcon:find("rbxassetid://") then
            TIcon = false
        else
            local stripped = TIcon:gsub("rbxassetid://", "")
            if #stripped < 6 then TIcon = false end
        end

        local TabSelect = Make("Button", MainScroll, {
            Size = UDim2.new(1, 0, 0, 24)
        })
        ApplyBorder(TabSelect)
        Make("Corner", TabSelect)

        local LabelTitle = InsertTheme(Create("TextLabel", TabSelect, {
            Size = UDim2.new(1, TIcon and -25 or -15, 1),
            Position = UDim2.fromOffset(TIcon and 25 or 15),
            BackgroundTransparency = 1,
            Font = MyLibrary.CurrentFont,
            Text = TName,
            TextColor3 = Theme["Color Text"],
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTransparency = (FirstTab and 0.3) or 0,
            TextTruncate = "AtEnd"
        }), "Text")

        local LabelIcon = InsertTheme(Create("ImageLabel", TabSelect, {
            Position = UDim2.new(0, 8, 0.5),
            Size = UDim2.new(0, 13, 0, 13),
            AnchorPoint = Vector2.new(0, 0.5),
            Image = TIcon or "",
            BackgroundTransparency = 1,
            ImageTransparency = (FirstTab and 0.3) or 0
        }), "Text")

        local Selected = InsertTheme(Create("Frame", TabSelect, {
            Size = FirstTab and UDim2.new(0, 4, 0, 4) or UDim2.new(0, 4, 0, 13),
            Position = UDim2.new(0, 1, 0.5),
            AnchorPoint = Vector2.new(0, 0.5),
            BackgroundColor3 = Theme["Color Theme"],
            BackgroundTransparency = FirstTab and 1 or 0
        }), "Theme")
        Make("Corner", Selected, UDim.new(0.5, 0))

        local Container = InsertTheme(Create("ScrollingFrame", {
            Size = UDim2.new(1, 0, 1, 0),
            Position = UDim2.new(0, 0, 1),
            AnchorPoint = Vector2.new(0, 1),
            ScrollBarThickness = 1.5,
            BackgroundTransparency = 1,
            ScrollBarImageTransparency = 0.2,
            ScrollBarImageColor3 = Theme["Color Theme"],
            AutomaticCanvasSize = "Y",
            ScrollingDirection = "Y",
            BorderSizePixel = 0,
            CanvasSize = UDim2.new(),
            Name = ("Container %i [ %s ]"):format(#ContainerList + 1, TName)
        }, {
            Create("UIPadding", {
                PaddingLeft = UDim.new(0, 10),
                PaddingRight = UDim.new(0, 10),
                PaddingTop = UDim.new(0, 10),
                PaddingBottom = UDim.new(0, 10)
            }),
            Create("UIListLayout", { Padding = UDim.new(0, 5) })
        }), "ScrollBar")
        ApplyBorder(Container)

        table.insert(ContainerList, Container)
        if not FirstTab then Container.Parent = Containers end

        local Tab = {}

        local function Tabs()
            if Container.Parent then return end
            for _, Frame in ipairs(ContainerList) do
                if Frame ~= Container then
                    Frame.Parent = nil
                end
            end
            Container.Parent = Containers
            Container.Size = UDim2.new(1, 0, 1, 150)
            for _, Other in ipairs(MyLibrary.Tabs) do
                if Other.Cont ~= Container then
                    Other.func:Disable()
                end
            end
            CreateTween({Container, "Size", UDim2.new(1, 0, 1, 0), 0.3})
            CreateTween({LabelTitle, "TextTransparency", 0, 0.35})
            CreateTween({LabelIcon, "ImageTransparency", 0, 0.35})
            CreateTween({Selected, "Size", UDim2.new(0, 4, 0, 13), 0.35})
            CreateTween({Selected, "BackgroundTransparency", 0, 0.35})
        end
        TabSelect.Activated:Connect(Tabs)

        FirstTab = true
        table.insert(MyLibrary.Tabs, {TabInfo = {Name = TName, Icon = TIcon}, func = Tab, Cont = Container})
        Tab.Cont = Container

        function Tab:Disable()
            Container.Parent = nil
            CreateTween({LabelTitle, "TextTransparency", 0.3, 0.35})
            CreateTween({LabelIcon, "ImageTransparency", 0.3, 0.35})
            CreateTween({Selected, "Size", UDim2.new(0, 4, 0, 4), 0.35})
            CreateTween({Selected, "BackgroundTransparency", 1, 0.35})
        end

        function Tab:Enable() Tabs() end

        function Tab:Visible(Bool)
            Funcs:ToggleVisible(TabSelect, Bool)
            if Bool == false then Container.Parent = nil end
        end

        function Tab:Destroy()
            TabSelect:Destroy()
            Container:Destroy()
        end

        -- componentes da aba (inclui AddSection expansivel, DropdownPlayer e DiscordInvite)
        AttachElements(Tab, Container, RowCtx)

        return Tab
    end

    ------------------------------------------------------------------
    -- FINALIZACAO
    ------------------------------------------------------------------
    CloseButton.Activated:Connect(function() Window:CloseBtn() end)
    MinimizeButton.Activated:Connect(function() Window:MinimizeBtn() end)

    -- Aplica as imagens salvas (JSON) ou as do tema
    task.spawn(function()
        task.wait(0.1)
        ProcessAndApplyImage(MyLibrary.HubImageLabel, CurrentImageSettings.HubImage or GetThemeImage("HubImage"), "Hub")
        ProcessAndApplyImage(MyLibrary.MinimizeExternalButton, CurrentImageSettings.MinimizeImage or GetThemeImage("MinimizeImage"), "Minimize")
        ProcessAndApplyImage(MyLibrary.TopbarImageLabel, CurrentImageSettings.TopbarImage or GetThemeImage("TopbarImage"), "Topbar")
    end)

    -- Aplica transparencia global salva
    if (MyLibrary.Save.GlobalTransparency or 0) > 0 then
        MyLibrary:SetGlobalTransparency(MyLibrary.Save.GlobalTransparency)
    end

    -- Aplica cor/transparencia das bordas
    for _, stroke in ipairs(MyLibrary.StrokeInstances) do
        if stroke and stroke.Parent then
            UpdateStroke(stroke)
        end
    end

    -- Carrega a tabela de traducao (link vem de MakeWindow ou usa o padrao da lib)
    task.spawn(LoadTranslations, TranslationSource)

    -- Janela de update: aparece so quando o conteudo e novo
    if type(UpdateCfg) == "table" then
        task.delay(1, function() Window:ShowUpdate(UpdateCfg) end)
    end

    return Window
end

return MyLibrary
